async function start(){
const {issueState,issueOutcome,resolutionBadges,operationSummary,orderSorts,sortOrders,pendingPaymentOrders,statuses,label,nextStep,milestones,canCancel,sumCentavos,stockExpired,cancellationChecks,needsAttention,paymentMethodLabel,processingEnd}=await import('/ui.mjs');
const {productThumbnail,installImageFallback}=await import('/product-images.mjs');
installImageFallback(document);
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let config={},me=null,csrf='',draft=null,offers=[],customers=[],order=null,quote=null,epoch=0,stage=1,page=1,noticeTimer,operationOrderId=null,currentProcessing=null,notifications=[];
let operationChoices=[],operationFilter='all',operationSearch='',operationLimit=8;

let profile=null,baseline='',draftActive=false,renderedHash=location.hash,pendingLeave=null;
const draftState=()=>JSON.stringify(draft&&{customer_id:draft.customer_id,seller_id:draft.seller_id,items:draft.items,payment_method:draft.payment_method,recipient_name:draft.recipient_name,recipient_contact:draft.recipient_contact,requested_delivery_address:draft.requested_delivery_address});
const dirty=()=>{captureDraft();return draftActive&&draftState()!==baseline;};
async function leave(work){if(busy.has('draft-mutation')||busy.has('submit')||busy.has('review-payment'))return;if(!dirty()){draftActive=false;return await work();}pendingLeave=work;openModal('Save your changes?','<p>Your order has unsaved changes. Save it as a draft to continue later.</p><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><div class="actions modal-actions">'+action('keep-editing','Keep editing')+action('discard-draft','Discard changes')+action('save-and-leave','Save draft','primary')+'</div>');}
const savedRecipient=()=>({recipient_name:profile?.default_recipient_name||'',recipient_contact:profile?.contact_number||'',requested_delivery_address:profile?.default_delivery_address||''});
const busy=new Set(),PAGE_SIZE=10;
const validQuantity=n=>Number.isSafeInteger(n)&&n>0&&n<=100000;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const peso=value=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value||0));
const cents=value=>{const [w,f='']=String(value||'0').split('.');return Number(w)*100+Number(f.padEnd(2,'0'));};
const selected=(a,b)=>String(a)===String(b)?' selected':'';
const isStaff=()=>['staff','billing','delivery','inventory','seller'].includes(me?.role);
const thumbnail=product=>productThumbnail({...offers.find(o=>o.offer_id===product.offer_id),...product},{demo:config.demo===true});
const listTitle=()=>isStaff()?'Sales & orders':'My orders';
const paths={chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',orders:'M4 5h16v16H4z M8 5V3h8v2 M8 10h8 M8 14h8 M8 18h5',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',box:'m3 7 9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',check:'m5 12 4 4 10-10',card:'M3 5h18v14H3z M3 9h18 M7 15h4',truck:'M2 6h12v12H2z M14 10h4l4 4v4h-8 M5 18a2 2 0 1 0 4 0 M16 18a2 2 0 1 0 4 0',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',chevron:'m9 5 7 7-7 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',refresh:'M20 7V3l-4 4 M20 7a9 9 0 1 0 1 8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',logout:'M10 4H4v16h6 M10 12h11 M17 8l4 4-4 4',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 8 0 0 1 16 0v3',close:'m6 6 12 12 M6 18 18 6',back:'M19 12H5 M10 7l-5 5 5 5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const action=(name,text,kind='',attrs='')=>`<button type="button" data-action="${name}" class="${kind}" ${attrs}>${text}</button>`;
const link=(href,text,kind='')=>`<a class="button ${kind}" href="${href}">${text}</a>`;
const badge=status=>`<span class="badge ${statuses.includes(status)||status==='unsuccessful'?status:''}"><span class="status-dot"></span>${esc(label(status))}</span>`;
const orderBadge=o=>{const end=processingEnd(o);if(issueState(o).status==='resolved')return '<span class="badge '+end.condition+'">'+(end.condition==='cancelled'?'Cancelled':'Unsuccessful')+' · Issue resolved</span>';return end.title==='Cancelled — Refund pending'?'<span class="badge cancelled"><span class="status-dot"></span>Cancelled — Refund pending</span>':badge(end.condition);};
function date(value,withTime=false){if(!value)return '—';const d=new Date(value.includes('T')?value:value.replace(' ','T')+'Z');return Number.isNaN(d.valueOf())?'—':d.toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',...(withTime?{hour:'numeric',minute:'2-digit'}:{}),timeZone:'Asia/Manila'});}
function toast(message){const el=document.querySelector('#notice');el.textContent=message;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),5500);}
async function api(path,method='GET',data){let response;try{response=await fetch('/api'+path,{method,headers:{'content-type':'application/json','x-csrf-token':csrf},body:data===undefined?undefined:JSON.stringify(data)});}catch{throw new Error('We couldn’t connect. Check your connection and try again.');}let result;try{result=await response.json();}catch{throw new Error('We couldn’t read the server response. Try again.');}if(!response.ok){if(response.status===401&&me){me=null;login();}const error=new Error(response.status>=500?'We couldn’t complete that request. Please retry or contact the sales team.':result.error||'Request failed.');error.details=result.details;error.status=response.status;throw error;}return result;}
async function processing(key,button,work,text='Working…'){
 if(busy.has(key))return;busy.add(key);if(key==='draft-mutation')captureDraft();
 const targets=key==='login'?[...document.querySelectorAll('#login-form button[type="submit"],#register-form button[type="submit"],[data-action="demo-login"],[data-action="register"],[data-action="sign-in"]')]:button?[button]:[];
 if(key==='review-payment')targets.push(...document.querySelectorAll('#review-payment-method,#accept-prices,[data-action="submit-order"],[data-action="stage"],[data-action="save-draft"],[data-action="close-modal"]'));
 if(key==='dispatch')targets.push(...document.querySelectorAll('[data-action="dispatch"],#operation-order,#operation-search,#outcome-form select,#outcome-form textarea,#outcome-form button'));
 if(key==='draft-mutation'||key==='submit')targets.push(...document.querySelectorAll('#review-payment-method,#accept-prices,#draft-form input,#draft-form textarea,#draft-form select,[data-quantity],#seller-select,[data-action="stage"],[data-action="save-draft"],[data-action="stage-next"],[data-action="use-saved"],[data-action="someone-else"],[data-action="save-defaults"]'));
 const before=[...new Set(targets)].map(b=>({b,html:b.innerHTML,disabled:b.disabled}));targets.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});if(button)button.textContent=text;
 try{return await work();}finally{busy.delete(key);before.forEach(({b,html,disabled})=>{if(b.isConnected){if(b.tagName==='BUTTON')b.innerHTML=html;b.disabled=disabled;b.removeAttribute('aria-busy');}});}
}
const fieldError=(name)=>`<span class="field-error" id="error-${name}" data-error-for="${name}" aria-live="polite"></span>`;
function showErrors(errors,root=document){root.querySelectorAll('[data-error-for]').forEach(e=>e.textContent='');root.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));let first;for(const[name,message]of Object.entries(errors)){const el=root.querySelector(`[name="${name}"]`),target=root.querySelector(`[data-error-for="${name}"]`);if(target)target.textContent=message;if(el){el.setAttribute('aria-invalid','true');first??=el;}}first?.focus();return !Object.keys(errors).length;}
function formError(message,root=document){const target=root.querySelector('[data-form-error]');if(target){target.textContent=message;target.hidden=!message;target.focus();}else toast(message);}
function headingFocus(){document.querySelector('main h1')?.focus({preventScroll:true});}
function shell(content,section='orders'){
 const nav=(href,name,symbol,key)=>`<a href="${href}" class="nav-link ${section===key?'active':''}" ${section===key?'aria-current="page"':''}>${icon(symbol)}<span>${name}</span></a>`;
 app.innerHTML=`<a href="#main-content" class="skip-link">Skip to content</a><aside class="sidebar"><a class="brand" aria-label="BSIT-44 Sales-Order Management" href="#orders"><span class="brand-mark">${icon('box')}</span><span class="brand-copy">BSIT-44<small>Sales-Order Management</small></span></a><div class="nav-caption">${isStaff()?'SALES WORKSPACE':'YOUR WORKSPACE'}</div><nav aria-label="Main navigation">${me.role==='staff'?nav('#overview','Sales Overview','chart','overview'):''}${nav('#orders',listTitle(),'orders','orders')}${!isStaff()?nav('#new','Create order','plus','new'):''}${isStaff()?(me.role==='staff'?nav('#inbox','Sales inbox','orders','inbox'):'')+(me.role==='staff'?nav('#operations',config.demo?'Processing outcomes':'Integrations','settings','operations'):''):nav('#profile','My profile','user','profile')+nav('#notifications','Notifications'+(notifications.some(n=>!n.read_at)?' ('+notifications.filter(n=>!n.read_at).length+')':''),'orders','notifications')}</nav><div class="sidebar-help">${icon('check')}<p>One workspace.<br>Every order, a clear next step.</p></div><div class="sidebar-foot"><div class="account"><span class="avatar">${esc(me.email.slice(0,2).toUpperCase())}</span><div><strong title="${esc(me.email)}">${esc(me.email)}</strong><small>${isStaff()?'Sales team':'Customer account'}</small></div></div>${action('logout',icon('logout')+'Sign out','quiet')}</div></aside><div class="workspace"><header class="topbar"><span>BSIT-44 Sales-Order Management <span class="breadcrumb">/</span> <strong>${section==='overview'?'Sales Overview':section==='profile'?'My profile':section==='new'?'Create order':section==='operations'?'Processing outcome':section==='notifications'?'Notifications':listTitle()}</strong></span><div class="topbar-actions">${config.demo?'<span class="environment"><span class="status-dot"></span>Demo mode</span>':'<span class="live-label">Sales workspace</span>'}${action('logout',icon('logout')+'<span>Sign out</span>','quiet mobile-signout')}</div></header><main class="content${section==='overview'?' overview-page':''}" id="main-content" tabindex="-1">${content}</main><footer class="app-footer"><span>BSIT-44 Sales-Order Management</span><span>${config.demo?'Demo photos are illustrative. Service results are simulated.':'Product totals are shown in PHP.'}</span></footer></div>`;
}
function login(error='',email=''){
 app.innerHTML=`<main class="login"><section class="login-story"><a class="brand" aria-label="BSIT-44 Sales-Order Management" href="#"><span class="brand-mark">${icon('box')}</span><span class="brand-copy">BSIT-44<small>Sales-Order Management</small></span></a><div class="story-content"><div class="eyebrow">FROM FIRST ITEM TO FINAL DELIVERY</div><h1>Every order.<br>A clear next step.</h1><p>A simple place to create purchases, follow progress, and keep the details together.</p><ol class="process-illustration" aria-label="The order process">${[['orders','Order','Build your purchase'],['box','Reservation','Check stock availability'],['card','Payment','Wait for verified payment'],['truck','Delivery','Track through confirmation']].map(([i,t,s],n)=>`<li><span class="process-icon">${icon(i)}</span><div><strong>${t}</strong><small>${s}</small></div><span class="process-index">0${n+1}</span></li>`).join('')}</ol></div><p class="login-footer">BSIT-44 <span>Sales-Order Management</span></p></section><section class="login-form"><div class="login-card"><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>Welcome back.</h2><p>Sign in to create orders and follow their progress.</p><form id="login-form" novalidate><div class="error" id="login-error" role="alert" data-form-error tabindex="-1" ${error?'':'hidden'}>${esc(error)}</div><label>Email address<input name="email" type="email" autocomplete="username" value="${esc(email)}" placeholder="you@example.edu" aria-describedby="error-email" required>${fieldError('email')}</label><label>Password<span class="password-control"><input id="password-input" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" aria-describedby="error-password" required maxlength="200">${action('toggle-password',icon('eye')+'<span>Show</span>','password-toggle','aria-label="Show password" aria-pressed="false" aria-controls="password-input"')}</span>${fieldError('password')}</label><button class="primary full" type="submit">Sign in ${icon('arrow')}</button></form>${config.demo?`<details class="demo-accounts"><summary>Try a demo account <span>Local demo</span></summary><p>Select an account to sign in instantly with fictional demo data. No real payments or shipments are created.</p><div class="demo-users">${[['admin@example.test','Sales team','Manage demo orders'],['alex@example.test','Alex Santos','View Alex’s orders'],['jamie@example.test','Jamie Reyes','View Jamie’s orders']].map(([email,name,help])=>action('demo-login',`<span class="avatar">${icon(email.startsWith('admin')?'orders':'user')}</span><span><strong>${name}</strong><small>${help}</small></span>${icon('arrow')}`,'demo-account',`data-email="${email}"`)).join('')}</div><small class="demo-credentials">Demo password: <code>CampusDemo2026!</code></small></details>`:''}<p class="account-switch">New here? ${action('register','Create a customer account','link')}</p><p class="login-note">${icon('check')}Access is based on your signed-in account.</p></div></section></main>`;
 document.title='Sign in · BSIT-44 Sales-Order Management';
}

function registration(){login();document.querySelector('.login-card').innerHTML='<div class="eyebrow">CUSTOMER ACCOUNT</div><h2>Create your account</h2><p>Save your details and keep your orders together.</p><form id="register-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div>'+[['name','Full name','text','name'],['email','Email address','email','email'],['password','Password (12–200 characters)','password','new-password'],['password_confirmation','Confirm password','password','new-password']].map(([name,label,type,autocomplete])=>'<label>'+label+'<input name="'+name+'" type="'+type+'" autocomplete="'+autocomplete+'" required maxlength="'+(name==='name'?150:name==='email'?255:200)+'">'+fieldError(name)+'</label>').join('')+'<button type="submit" class="primary full">Create account</button></form><p>Already registered? '+action('sign-in','Sign in','link')+'</p>';}
function profileView(){shell('<div class="page-head"><div><div class="eyebrow">YOUR ACCOUNT</div><h1 tabindex="-1">My profile</h1><p>Saved details prefill new orders. Existing orders keep their own recipient details.</p></div></div><section class="panel profile-panel"><div class="panel-head"><h2>Contact, delivery and payment preferences</h2></div><form id="profile-form" class="panel-body form-grid" novalidate><div class="error span-all" data-form-error role="alert" tabindex="-1" hidden></div><p class="span-all">Account: '+esc(profile.email)+'</p>'+[['customer_name','Full name',150,'name'],['contact_number','Contact number',30,'tel'],['default_recipient_name','Default recipient name',150,'shipping name'],['default_delivery_address','Default delivery address',3000,'shipping street-address']].map(([key,title,max,autocomplete])=>'<label class="'+(key==='default_delivery_address'?'span-all':'')+'">'+title+(key==='default_delivery_address'?'<textarea name="'+key+'" maxlength="'+max+'" autocomplete="'+autocomplete+'">'+esc(profile[key])+'</textarea>':'<input name="'+key+'" maxlength="'+max+'" value="'+esc(profile[key])+'" autocomplete="'+autocomplete+'" '+(key==='customer_name'?'required':'')+'>')+fieldError(key)+'</label>').join('')+'<label class="span-all">Preferred payment method<select name="preferred_payment_method"><option value="">Choose on each order</option>'+config.payment_methods.map(x=>'<option value="'+x.value+'"'+selected(x.value,profile.preferred_payment_method)+'>'+esc(x.label)+'</option>').join('')+'</select><span class="field-hint">Prefills new orders. You can change it before submitting; existing orders keep their payment method.</span></label><p class="field-hint span-all">You can leave default delivery fields incomplete and finish them on each order.</p><div class="span-all actions"><button type="submit" class="primary">Save profile</button></div></form></section>','profile');}
function defaultsControls(){if(isStaff())return '';const missing=[['default_recipient_name','recipient name'],['contact_number','contact number'],['default_delivery_address','delivery address']].filter(([key])=>!profile?.[key]?.trim()).map(([,name])=>name);return '<div class="span-all saved-details"><div class="actions">'+action('use-saved','Use my saved details','secondary')+action('someone-else','Deliver to someone else','quiet')+'</div><p class="field-hint">'+(missing.length?'Missing from saved details: '+missing.join(', ')+'. Complete these for this order or in My profile.':'Your saved details are available.')+'</p>'+action('save-defaults','Save as my default details','secondary')+'</div>';}

async function signIn(email,password){const result=await api('/login','POST',{email,password});me=result.user;csrf=result.csrf;page=1;sessionStorage.removeItem('orderFilters');if(location.hash!=='#orders')location.hash='orders';else await route();}
const skeleton=()=>`<div class="loading" role="status" aria-label="Loading workspace"><span class="spinner"></span> Loading your workspace…</div><div class="skeleton-cards" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="skeleton-panel" aria-hidden="true"></div>`;
async function route(){
 if(!me)return login();draftActive=false;renderedHash=location.hash;modal.close();const ticket=++epoch,hash=location.hash.slice(1)||'orders';shell(skeleton(),hash==='overview'?'overview':hash==='operations'?'operations':hash==='new'||hash.startsWith('edit/')?'new':'orders');
 try{
  if(!isStaff()){notifications=await api('/notifications');if(ticket!==epoch)return;}
  if(hash==='profile'){profile=await api('/profile');if(ticket!==epoch)return;profileView();}
  else if(hash==='overview')await overviewView(ticket);
  else if(hash==='orders')await orderList(ticket);
  else if(hash==='new'||/^edit\/\d+$/.test(hash)){
   if(isStaff())throw new Error('Drafts belong to customer accounts. Open a submitted order from Sales & orders.');
   const data=await Promise.all([api('/offers'),api('/customers'),isStaff()?null:api('/profile')]);if(ticket!==epoch)return;[offers,customers,profile]=data;
   if(hash.startsWith('edit/')){order=await api('/orders/'+hash.split('/')[1]);if(ticket!==epoch)return;if(order.order_status!=='draft')throw new Error('This order is already submitted and its purchase details are locked.');draft={...order,items:order.items.map(i=>({offer_id:i.offer_id,quantity:i.quantity}))};}
   else{order=null;draft={customer_id:isStaff()?customers[0]?.customer_id||'':me.customer_id,seller_id:offers[0]?.seller_id||'',items:[],payment_method:!isStaff()&&config.payment_methods?.some(x=>x.value===profile?.preferred_payment_method)?profile.preferred_payment_method:config.payment_methods?.[0]?.value||'prepaid',recipient_name:'',recipient_contact:'',requested_delivery_address:'',...(!isStaff()?savedRecipient():{})};}
   stage=1;quote=null;baseline=draftState();draftActive=true;draftView();
  }else if(/^order\/\d+$/.test(hash)){const result=await Promise.all([api('/orders/'+hash.split('/')[1]),api('/offers').catch(()=>[])]);if(ticket!==epoch)return;[order,offers]=result;if(order.order_status!=='draft'){const r=await api('/orders/'+order.order_id+'/resolution');if(ticket!==epoch)return;order.resolution=r;}detailView();resolutionSelection();}
  else if(hash==='inbox'){const rows=await api('/sales-inbox');if(ticket!==epoch)return;shell(`<div class="page-head"><h1>Sales inbox</h1>${action('refresh','Refresh','secondary')}</div><section class="panel"><div class="panel-body"><p>Customer messages awaiting a reply appear first. Open an order to reply.</p>${rows.map(m=>`<article class="notification-card"><div><strong>${esc(m.order_number)} · ${esc(m.customer_name)}</strong><small>${m.sender_role==='customer'?'Awaiting Sales reply':'Sales replied'} · ${date(m.created_at,true)}</small><p>${esc(m.body)}</p></div>${link('#order/'+m.order_id,'Open conversation','secondary')}</article>`).join('')||'<p>No conversations yet.</p>'}</div></section>`,'inbox');}
  else if(hash==='notifications'){if(isStaff())throw new Error('Customer notifications are available in customer accounts.');notificationsView();}
  else if(hash==='operations'){const requests=await api('/operations/requests');if(ticket!==epoch)return;await operations(requests,ticket);}
  else{location.hash='orders';return;}
  if(ticket===epoch){document.title=`${document.querySelector('main h1')?.textContent||'Orders'} · BSIT-44 Sales-Order Management`;headingFocus();}
 }catch(error){if(ticket===epoch&&me)shell(`<div class="empty error-state">${icon('alert')}<h1 tabindex="-1">We couldn’t load this page</h1><p>${esc(error.message)}</p><div class="actions">${action('refresh',icon('refresh')+'Try again','primary')}${hash==='overview'?action('overview-reset','Reset reporting period','secondary'):''}${link('#orders','Back to orders')}</div></div>`);}
}
const filters=()=>new URLSearchParams(sessionStorage.getItem('orderFilters')||'');
let overviewFilters={period:'month'};try{overviewFilters=JSON.parse(sessionStorage.getItem('overviewFilters')||'null')||overviewFilters;}catch{}
function overviewDate(value,monthly=false){return new Date(value+(monthly?'-01':'')+'T00:00:00+08:00').toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',...(monthly?{}:{day:'numeric'}),year:'numeric'});}
let overviewObserver;
function renderOverviewChart(rows){
 overviewObserver?.disconnect();
 const host=document.querySelector('#overview-trend');if(!host)return;
 host.addEventListener('focusin',e=>host.onpointerover?.(e));
 host.addEventListener('focusout',()=>{const t=host.querySelector('.trend-tooltip');if(t)t.hidden=true;});
 let lastWidth;
 const draw=()=>{
  const width=Math.max(240,host.clientWidth);if(width===lastWidth)return;lastWidth=width;
  const focused=host.contains(document.activeElement)?document.activeElement.closest('[data-point]')?.dataset.point:null;
  const left=58,right=12,top=18,bottom=264,plot=width-left-right,slot=plot/rows.length;
  const max=Math.max(...rows.map(x=>x.value),0),raw=(max||1)/4,power=10**Math.floor(Math.log10(raw));
  const step=([1,2,2.5,5,10].find(x=>x*power>=raw)||10)*power,ceiling=Math.ceil((max||1)/step)*step;
  const ticks=Math.min(rows.length,Math.max(2,Math.min(7,Math.floor(plot/76)+1))),indices=new Set(Array.from({length:ticks},(_,i)=>Math.round(i*(rows.length-1)/Math.max(1,ticks-1))));
  const axis=n=>'₱'+new Intl.NumberFormat('en-PH',{notation:'compact',maximumFractionDigits:2}).format(n);
  host.innerHTML=`<svg class="trend-chart" viewBox="0 0 ${width} 300" width="${width}" height="300" role="group" aria-label="Payments collected; each period has a focusable amount">${Array.from({length:Math.round(ceiling/step)+1},(_,i)=>{const amount=i*step,y=bottom-amount/ceiling*(bottom-top);return `<line x1="${left}" x2="${width-right}" y1="${y}" y2="${y}" stroke="#e5ece5"/><text x="${left-10}" y="${y+4}" text-anchor="end">${axis(amount)}</text>`;}).join('')}${rows.map((x,i)=>{const center=left+(i+.5)*slot,height=x.value/ceiling*(bottom-top),bar=Math.min(28,slot*.65);return `<g tabindex="0" role="button" data-point="${i}" data-amount="${x.value}" aria-label="${esc(x.title)}: ${esc(peso(x.value))}"><rect class="trend-hit" x="${left+i*slot}" y="${top}" width="${slot}" height="${bottom-top}" fill="transparent"/><rect x="${center-bar/2}" y="${bottom-height}" width="${bar}" height="${height}" rx="2" fill="#48A04C" pointer-events="none"/>${indices.has(i)?`<text x="${rows.length===1?center:i===0?left:i===rows.length-1?width-right:center}" y="289" text-anchor="${rows.length===1?'middle':i===0?'start':i===rows.length-1?'end':'middle'}">${esc(x.axis)}</text>`:''}</g>`;}).join('')}</svg><div class="trend-tooltip" role="status" hidden></div>`;
  const tooltip=host.querySelector('.trend-tooltip');
  const show=event=>{const point=event.target.closest('[data-point]');if(!point)return;const x=rows[Number(point.dataset.point)];tooltip.textContent=x.title+' · '+peso(x.value);tooltip.hidden=false;};
  host.onpointerover=show;host.onfocusin=show;host.onclick=show;
  host.onpointerleave=()=>{tooltip.hidden=true;};host.onfocusout=()=>{tooltip.hidden=true;};host.onkeydown=e=>{if(e.key==='Escape')tooltip.hidden=true;if(e.key==='Enter'||e.key===' '){e.preventDefault();show(e);}};
  if(focused!=null)host.querySelector('[data-point="'+focused+'"]')?.focus({preventScroll:true});
 };
 draw();overviewObserver=new ResizeObserver(draw);overviewObserver.observe(host);
}

async function overviewView(ticket){
 if(me.role!=='staff')throw new Error('Sales Overview is available only to Sales administrators and staff.');
 const data=await api('/sales-overview?'+new URLSearchParams(overviewFilters));if(ticket!==epoch)return;
 const {period,cards}=data;
 const card=(title,value,explanation,symbol='card')=>`<div class="stat"><span class="stat-icon">${icon(symbol)}</span><small>${title} <span class="calculation-help" tabindex="0" title="${esc(explanation)}" aria-label="${esc(explanation)}">ⓘ</span></small><strong class="value">${value}</strong></div>`;
 const rows=data.trend.map(x=>({title:overviewDate(x.date,period.grouping==='monthly'),axis:new Date(x.date+(period.grouping==='monthly'?'-01':'')+'T00:00:00+08:00').toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',...(period.grouping==='monthly'?{year:'2-digit'}:{day:'numeric'})}),value:Number(x.amount)}));
 shell(`<div class="page-head"><div><div class="eyebrow">SALES WORKSPACE</div><h1 tabindex="-1">Sales Overview</h1><p>Collections and completed product sales.</p></div>${action('refresh',icon('refresh')+'Refresh')}</div><section class="panel"><div class="panel-head"><h2>Reporting period</h2></div><div class="panel-body"><form id="overview-filter-form" class="overview-filters"><div class="error" data-form-error role="alert" hidden></div><label>Period<select name="period" id="overview-period">${[['today','Today'],['7days','Last 7 days'],['month','This month'],['custom','Custom date range']].map(([v,t])=>`<option value="${v}"${selected(v,period.preset)}>${t}</option>`).join('')}</select></label><label>From<input type="date" name="from" value="${period.from}" ${period.preset!=='custom'?'disabled':''}></label><label>To<input type="date" name="to" value="${period.to}" ${period.preset!=='custom'?'disabled':''}></label><button class="primary" type="submit">Apply period</button></form><p class="reporting-period">${overviewDate(period.from)} – ${overviewDate(period.to)} · Philippine time (Asia/Manila)</p></div></section><div class="stats overview-stats">${card('Payments collected',peso(cards.payments_collected),'Verified product payments recorded in this period, including payments on later-cancelled or unsuccessful orders. Counted once per order using its matching Billing verification record.')}${card('Refunds recorded',peso(cards.refunds_recorded),'Completed external refunds recorded during this period. Pending and failed refund attempts are excluded.')}${card('Net collections',peso(cards.net_collections),'Payments collected minus completed refunds recorded in this period. This can be negative when prior-period collections are refunded.')}${card('Completed orders',cards.completed_orders,'Orders with completed fulfillment, verified payment and verified delivery, grouped by recorded completion date. Cancelled, unsuccessful and issue-resolved cases are excluded.','check')}</div><p class="scope-note">Collection basis: Billing verification date; refunds use their recorded completion date. Product totals only — no delivery fees, taxes or other charges are added. Completed-sales tables use the completion date.</p>${data.empty?'<div class="note">No sales in this period.</div>':''}
 <div class="overview-charts"><section class="panel trend-panel"><div class="panel-head"><h2>Payments collected</h2><small>${period.grouping==='monthly'?'Monthly':'Daily'} · PHP</small></div><div class="panel-body"><div class="trend-scroll" id="overview-trend"></div><details class="trend-values"><summary>View trend values</summary><table><thead><tr><th>Period</th><th>Collections</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.title)}</td><td>${peso(x.value)}</td></tr>`).join('')}</tbody></table></details></div></section><section class="panel products-panel"><div class="panel-head"><h2>Top-selling products</h2><small title="${esc(data.limitations.refund_allocation)}">Top five · units sold</small></div><div class="panel-body">${data.products.length?`<ol class="product-ranking">${data.products.map((x,i)=>`<li><span class="product-rank">${i+1}</span><div class="product-result"><details class="product-name"><summary title="${esc(x.product_name)}">${esc(x.product_name)}</summary><p>${esc(x.product_name)}</p></details><div class="product-figures"><span>${x.quantity.toLocaleString()} ${x.quantity===1?'unit':'units'}</span><strong>${peso(x.sales_amount)}</strong></div><svg class="product-bar" viewBox="0 0 100 4" preserveAspectRatio="none" aria-hidden="true"><rect width="100" height="4" rx="2" fill="#edf3ed"/><rect width="${100*x.quantity/Math.max(...data.products.map(p=>p.quantity),1)}" height="4" rx="2" fill="#48A04C"/></svg></div></li>`).join('')}</ol>`:'<p class="products-empty">No completed sales in this period.</p>'}</div></section></div>
 <section class="panel"><div class="panel-head"><h2>Recent sales</h2><small>Most recent 10 completed sales</small></div><div class="panel-body"><p>Completed product sales for the full selected period: <strong>${peso(data.completed_sales)}</strong></p>${data.recent.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Completed</th><th>Product sales</th><th>Payment</th><th>Action</th></tr></thead><tbody>${data.recent.map(x=>`<tr><td>${esc(x.order_number)}</td><td>${esc(x.customer_name)}</td><td>${date(x.completed_at,true)}</td><td>${peso(x.sales_amount)}</td><td>${badge(x.payment_status)}</td><td>${link('#order/'+x.order_id,'View order','secondary')}</td></tr>`).join('')}</tbody></table></div>`:'<p>No sales in this period.</p>'}</div></section>${data.limitations.unmapped_payments||data.limitations.unmapped_completions||data.limitations.externally_documented_settlements?`<section class="panel"><div class="panel-body"><h2>Data coverage</h2><p>These coverage notes apply across stored records; missing dates cannot be assigned to a reporting period.</p>${data.limitations.unmapped_payments?`<p>${data.limitations.unmapped_payments} verified payment records lack a matching dated Billing event and are excluded from period collections.</p>`:''}${data.limitations.unmapped_completions?`<p>${data.limitations.unmapped_completions} completed orders lack a completion timestamp and are excluded from period sales.</p>`:''}${data.limitations.externally_documented_settlements?'<p>Externally documented issue settlements do not change the payment ledger and are excluded from collections until Billing records verification.</p>':''}</div></section>`:''}`,'overview');
 renderOverviewChart(rows);
}

async function orderList(ticket){
 const params=filters();if(isStaff()&&params.get('status')==='draft'){params.delete('status');sessionStorage.setItem('orderFilters',params.toString());}
 const [all,rows]=await Promise.all([api('/orders'),api('/orders?'+params)]);if(ticket!==epoch)return;
 const active=rows.filter(o=>Boolean(o.order_date)&&!['draft','cancelled','completed'].includes(o.order_status)&&!processingEnd(o).finished);
 const pendingPayments=pendingPaymentOrders(rows);
 const totalPages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));page=Math.min(page,totalPages);const visible=sortOrders(rows,params.get('sort')||'newest').slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
 const chips=[['','All'],...(!isStaff()?[['draft','Drafts']]:[]),['pending_stock','Pending stock'],['awaiting_payment','Awaiting payment'],['completed','Completed'],['cancelled','Cancelled'],['unsuccessful','Unsuccessful'],...(isStaff()?[['confirmed','Confirmed'],['fulfilling','Fulfilling'],['cancellation_pending','Cancellation requests'],['attention','Needs attention']]:[])];
 const applied=[...params].map(([key,v])=>`<span class="filter-chip">${esc({search:'Search',status:'Status',from:'From',to:'To',sort:'Sort by'}[key])}: ${esc(key==='status'?label(v):key==='sort'?orderSorts.find(x=>x[0]===v)?.[1]||v:v)}</span>`).join('');
 const row=o=>`<tr><td><a class="order-number" href="#order/${o.order_id}">${esc(o.order_number)}</a><small>${esc(o.seller_name)} · ${o.item_count} ${Number(o.item_count)===1?'item':'items'}</small><small>${esc(paymentMethodLabel(o.payment_method))}</small>${isStaff()?`<small>${esc(o.customer_name)}</small>`:''}</td><td>${orderBadge(o)}${resolutionBadges(o).map(x=>`<small class="resolution-work-badge${x==='Issue resolved'?' issue-resolved':''}">${esc(x)}</small>`).join('')}<small class="next-step">${esc(nextStep(o,isStaff()))}</small></td><td>${date(o.created_at)}<small>Updated ${date(o.updated_at)}</small></td><td class="amount"><strong>${peso(o.order_total)}</strong></td><td class="row-action"><a href="#order/${o.order_id}" class="view-link">View order ${icon('chevron')}</a></td></tr>`;
 shell(`<div class="page-head"><div><div class="eyebrow">${isStaff()?'SALES WORKSPACE':'YOUR ORDER WORKSPACE'}</div><h1 tabindex="-1">${listTitle()}</h1><p>${isStaff()?'Manage purchases and keep every order moving.':'Create an order, continue a draft, or follow a delivery.'}</p></div>${!isStaff()?link('#new',icon('plus')+'Create order','primary'):''}</div><div class="stats order-count-stats"><div class="stat"><span class="stat-icon">${icon('orders')}</span><small>Total orders</small><strong>${rows.length}</strong></div><div class="stat active-orders${active.length>0?' has-active-orders':''}"><span class="stat-icon">${icon('box')}</span><small>Active orders</small><strong>${active.length}</strong></div><div class="stat"><span class="stat-icon">${icon('card')}</span><small>Awaiting payment</small><strong>${pendingPayments.length}</strong></div></div><p class="scope-note">Counts use all matching permitted orders. Active orders exclude drafts, completed orders and stopped fulfillment. Refunds and returns remain visible under Needs attention.</p>${isStaff()&&all.some(needsAttention)?`<div class="attention-note">${icon('alert')}<span><strong>${all.filter(needsAttention).length} ${all.filter(needsAttention).length===1?'order needs':'orders need'} attention.</strong> Open the flagged orders to review service results.</span></div>`:''}${!isStaff()&&notifications.length?`<section class="panel"><div class="panel-head"><h2>Order updates</h2>${link('#notifications','All notifications')}</div><div class="panel-body">${notificationCards(notifications.slice(0,3))}</div></section>`:''}<section class="panel orders-panel"><div class="panel-head"><div><h2>${isStaff()?'Order workspace':'Your orders'}</h2><p>${isStaff()?'Monitor customer orders, review service results, and coordinate cancellations.':'Find a purchase or pick up where you left off.'}</p></div><span class="result-count">${rows.length} ${rows.length===1?'result':'results'}</span></div><nav class="status-tabs" aria-label="Order status shortcuts">${chips.map(([value,name])=>action('status-filter',`${name}<span>${value?all.filter(o=>value==='attention'?needsAttention(o):['cancelled','unsuccessful'].includes(value)?issueOutcome(o)===value:o.order_status===value).length:all.length}</span>`,'status-tab'+((params.get('status')||'')===value?' active':''),`data-status="${value}" aria-pressed="${(params.get('status')||'')===value}"`)).join('')}</nav><details class="filter-scope"><summary>Filter help and limits</summary>Created date filters use UTC; displayed dates use Philippine time. Shortcut counts cover all permitted orders before filters.</details><form class="toolbar" id="filter-form" novalidate><label class="search-field">Search orders<span class="search-control">${icon('search')}<input name="search" placeholder="${isStaff()?'Order number or customer':'Order number'}" value="${esc(params.get('search')||'')}" maxlength="150"></span></label><label>Status<select name="status"><option value="">All statuses</option>${[...statuses,'unsuccessful'].filter(s=>!isStaff()||s!=='draft').concat(isStaff()?['attention']:[]).map(s=>`<option value="${s}"${selected(s,params.get('status'))}>${label(s)}</option>`).join('')}</select></label><label>Sort by<select name="sort">${orderSorts.map(([value,title])=>`<option value="${value}"${selected(value,params.get('sort')||'newest')}>${title}</option>`).join('')}</select></label><label>Created from<input type="date" name="from" value="${esc(params.get('from')||'')}"></label><label>Created to<input type="date" name="to" value="${esc(params.get('to')||'')}"></label><div class="filter-buttons"><button class="primary" type="submit">Apply</button>${action('reset-filters','Reset','quiet')}</div><div class="field-error span-all" data-error-for="dates" role="alert"></div></form>${params.size?`<div class="active-filters" aria-label="Active filters">${applied}${action('reset-filters','Clear all','link')}</div>`:''}${rows.length?`<div class="desktop-orders table-wrap"><table><thead><tr><th>${isStaff()?'Order / customer':'Order / seller'}</th><th>Status & next step</th><th>Created / updated</th><th class="amount">Product total</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${visible.map(row).join('')}</tbody></table></div><div class="mobile-orders">${visible.map(o=>`<article class="order-card"><div class="card-top"><a class="order-number" href="#order/${o.order_id}">${esc(o.order_number)}</a>${orderBadge(o)}</div><p>${esc(o.seller_name)} · ${o.item_count} items${isStaff()?' · '+esc(o.customer_name):''}</p>${resolutionBadges(o).map(x=>`<p class="resolution-work-badge${x==='Issue resolved'?' issue-resolved':''}">${esc(x)}</p>`).join('')}<div class="card-next">${icon('clock')}${esc(nextStep(o,isStaff()))}</div><div class="card-bottom"><div><strong>${peso(o.order_total)}</strong><small>${date(o.created_at)}</small></div><a class="view-link" href="#order/${o.order_id}">View order ${icon('chevron')}</a></div></article>`).join('')}</div><div class="table-foot"><span>Showing ${(page-1)*PAGE_SIZE+1}–${Math.min(page*PAGE_SIZE,rows.length)} of ${rows.length}</span><div class="pagination">${action('page-prev','Previous','','aria-label="Previous page" '+(page===1?'disabled':''))}<span>Page ${page} of ${totalPages}</span>${action('page-next','Next','','aria-label="Next page" '+(page===totalPages?'disabled':''))}</div></div>`:`<div class="empty"><span class="empty-icon">${icon(params.size?'search':'orders')}</span><h3>${params.size?'No matching orders':isStaff()?'No customer orders yet':'Your orders start here'}</h3><p>${params.size?` ${params.get('status')?'No orders '+esc(params.get('status')==='attention'?'needing attention':label(params.get('status')).toLowerCase())+'. ':''}Try another search or clear your filters.`:isStaff()?'Customer orders will appear here after submission.':'Create your first order and track its progress here.'}</p>${params.size?action('reset-filters','Clear filters','primary'):isStaff()?'':link('#new',icon('plus')+'Create an order','primary')}</div>`}</section>`);
}
function captureDraft(){if(busy.has('draft-mutation')&&document.querySelector('#draft-form input:disabled'))return;const form=document.querySelector('#draft-form');if(form){for(const[key,value]of new FormData(form))draft[key]=value;if(isStaff())draft.customer_id=Number(draft.customer_id);}if(draft&&!isStaff())draft.customer_id=me.customer_id;}
function selectedItems(){return draft.items.map(i=>{const offer=offers.find(o=>o.offer_id===i.offer_id);return {...i,...offer,unit:offer?cents(offer.selling_price):0,name:offer?.product_name||`Unavailable offer #${i.offer_id}`};});}
function stageIndicator(){return `<ol class="stages" aria-label="Create order stages">${['Select items','Recipient details','Review order'].map((name,i)=>`<li class="${stage===i+1?'current':stage>i+1?'done':''}" ${stage===i+1?'aria-current="step"':''}>${action('stage',`<span class="stage-number">${stage>i+1?icon('check'):i+1}</span><span>${name}</span>`,'',`data-stage="${i+1}" ${i+1>stage?'disabled':''}`)}</li>`).join('')}</ol>`;}
function summary(){
 const items=stage===3&&quote?quote.items.map(i=>({name:i.product_name_at_order,quantity:i.quantity,unit:cents(i.unit_price_at_order)})):selectedItems();
 const total=items.reduce((s,i)=>s+i.unit*(validQuantity(i.quantity)?i.quantity:0),0),seller=offers.find(o=>o.seller_id===Number(draft.seller_id))?.seller_name||'Choose a seller';
 return `<aside class="summary-column"><section class="panel summary"><div class="panel-head"><h2>Order summary</h2><span class="summary-icon">${icon('orders')}</span></div><div class="panel-body"><div class="summary-seller"><small>SELLER</small><strong>${esc(seller)}</strong></div>${items.length?items.map(i=>`<div class="summary-item"><div>${esc(i.name)}<small>${i.quantity} × ${peso(i.unit/100)}</small></div><strong>${peso(i.unit*i.quantity/100)}</strong></div>`).join(''):'<p class="summary-empty">Your selected products will appear here.</p>'}<div class="summary-row total"><span>Product total</span><strong>${peso(total/100)}</strong></div><p class="money-note">PHP · Shipping, tax, and discounts are not included.</p><p class="payment-summary"><strong>Payment:</strong> ${esc(paymentMethodLabel(draft.payment_method))}</p>${stage===3?'<p class="note">Check the purchase details and accept the current prices to submit.</p>':''}<div class="summary-assurance">${icon('check')}Prices are checked by the server before submission.</div></div></section></aside>`;
}
function itemsTable(){const items=selectedItems();return items.length?`<div class="selected-items">${items.map(i=>`<div class="selected-item">${thumbnail(i)}<div class="selected-name"><strong>${esc(i.name)}</strong><small>${offers.some(o=>o.offer_id===i.offer_id)?peso(i.unit/100)+' per unit':'No longer available'}</small></div><label class="quantity-label">Quantity<input type="number" min="1" max="100000" step="1" value="${i.quantity}" data-quantity="${i.offer_id}" aria-label="Quantity for ${esc(i.name)}" aria-describedby="quantity-${i.offer_id}"><span id="quantity-${i.offer_id}" class="sr-only">Positive whole numbers, up to 100,000</span></label><strong class="item-total">${peso(i.unit*i.quantity/100)}</strong>${action('remove-item',icon('close'),'icon-button',`data-id="${i.offer_id}" aria-label="Remove ${esc(i.name)}"`)}</div>`).join('')}</div>`:'<div class="small-empty">No items selected. Add a product from the list above.</div>';}
function paymentControls(value=draft.payment_method,id='payment-method'){const choices=config.payment_methods||[{value:'prepaid',label:'Pay in advance'}];return `<label class="span-all">Payment method<select name="payment_method" id="${id}">${value==='prepaid'&&!choices.some(x=>x.value==='prepaid')?'<option value="prepaid">Pay in advance (saved order)</option>':''}${choices.map(x=>`<option value="${x.value}"${selected(x.value,value)}>${esc(x.label)}</option>`).join('')}</select><span class="field-hint">${value==='cod'?'Pay when the order arrives. Billing verifies collection after delivery.':'Pay before shipment. Billing verifies your payment.'}</span></label>`;}
function recipientFields(){return `<form id="draft-form" class="form-grid" novalidate><div class="error span-all" data-form-error role="alert" tabindex="-1" hidden></div>${isStaff()?`<label class="span-all">Customer<select name="customer_id" required aria-describedby="error-customer_id"><option value="">Select a customer</option>${customers.map(c=>`<option value="${c.customer_id}"${selected(c.customer_id,draft.customer_id)}>${esc(c.customer_name)} · ${esc(c.contact_number)}</option>`).join('')}</select>${fieldError('customer_id')}</label><div class="span-all">${action('new-customer',icon('plus')+'Add a customer','link')}</div>`:`<div class="customer-identity span-all">${icon('user')}<span>Ordering as <strong>${esc(customers.find(c=>c.customer_id===me.customer_id)?.customer_name||me.email)}</strong><small>Your order is linked to your signed-in account.</small></span></div>`}<label>Recipient name<input name="recipient_name" maxlength="150" value="${esc(draft.recipient_name)}" placeholder="Full name" autocomplete="name" required aria-describedby="error-recipient_name">${fieldError('recipient_name')}</label><label>Contact number<input name="recipient_contact" maxlength="30" value="${esc(draft.recipient_contact)}" placeholder="09XX XXX XXXX" type="tel" autocomplete="tel" required aria-describedby="error-recipient_contact">${fieldError('recipient_contact')}</label><label class="span-all">Delivery address<textarea name="requested_delivery_address" maxlength="3000" autocomplete="street-address" placeholder="House / building, street, barangay, city, province, postal code" required aria-describedby="error-requested_delivery_address">${esc(draft.requested_delivery_address)}</textarea>${fieldError('requested_delivery_address')}</label>${paymentControls()}${defaultsControls()}<p class="field-hint span-all">Edits apply only to this order unless you choose Save as my default details.</p></form>`;}
function reviewContent(inModal=false){const q=quote, o=inModal?order:draft;const changed=q.order_total!==String(o.order_total)||q.items.some(i=>i.unit_price_at_order!==String(order?.items.find(x=>x.offer_id===i.offer_id)?.unit_price_at_order)||i.product_name_at_order!==order?.items.find(x=>x.offer_id===i.offer_id)?.product_name_at_order);return `<div class="error" data-form-error role="alert" tabindex="-1" hidden></div><div class="note ${changed?'warning':''}">${icon(changed?'alert':'check')}<span>${changed?'The current names or prices differ from the saved draft. Review the revised details and explicitly accept them.':'Current product names, prices, and availability have been checked by the server.'}</span></div><div class="review-recipient"><small>DELIVER TO</small><strong>${esc(o.recipient_name)}</strong><span>${esc(o.recipient_contact)}</span><p>${esc(o.requested_delivery_address)}</p>${action(inModal?'edit-draft':'stage','Edit recipient details','link',inModal?'':'data-stage="2"')}</div>${paymentControls(o.payment_method,'review-payment-method')}<p class="review-payment"><strong>Payment method:</strong> ${esc(paymentMethodLabel(o.payment_method))}${o.payment_method==='cod'?' · No advance payment. Receive the order, then pay cash in person to the delivery staff. Billing verifies collection before the order is completed.':' · Pay first using this method after stock is reserved and Billing issues the payment request. Shipment starts only after Billing verifies payment.'}</p><div class="review-items">${q.items.map(i=>`<div class="review-line">${thumbnail(i)}<div><strong>${esc(i.product_name_at_order)}</strong><small>${i.quantity} × ${peso(i.unit_price_at_order)}</small></div><strong>${peso(cents(i.unit_price_at_order)*i.quantity/100)}</strong></div>`).join('')}</div><div class="summary-row total"><span>Product total</span><strong>${peso(q.order_total)}</strong></div><p class="money-note">No shipping, tax, or discounts are added.</p><label class="check acceptance"><input type="checkbox" id="accept-prices"><span>I accept the items, prices, payment method, and total shown above.</span></label><p class="field-error" data-error-for="acceptance" aria-live="polite"></p><div class="review-actions">${inModal?action('close-modal','Back'):action('stage','Back to recipient','','data-stage="2"')}<div class="actions">${!inModal?action('save-draft','Save draft','secondary'):''}${action('submit-order',`Submit order ${icon('arrow')}`,'primary','disabled')}</div></div>`;}
function draftView(focus){
 const sellers=[...new Map(offers.map(o=>[o.seller_id,o])).values()],choices=offers.filter(o=>o.seller_id===Number(draft.seller_id));
 let content;
 if(stage===1)content=`<section class="panel"><div class="panel-head"><div><h2>Select your products</h2><p>One seller per order. Add the same offer again to increase its quantity.</p></div><span class="step-label">STEP 1 OF 3</span></div><div class="panel-body"><label>Seller<select id="seller-select" aria-describedby="seller-help"><option value="" ${draft.seller_id?'':'selected'} disabled>Select a seller</option>${sellers.map(s=>`<option value="${s.seller_id}"${selected(s.seller_id,draft.seller_id)}>${esc(s.seller_name)}</option>`).join('')}</select><small id="seller-help">Changing seller clears the selected products after confirmation.</small></label><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><div class="product-list">${choices.map(o=>`<article class="offer-row">${thumbnail(o)}<div><h3>${esc(o.product_name)}</h3><p>${esc(o.description)}</p></div><div class="offer-price"><strong>${peso(o.selling_price)}</strong><small>per unit</small></div>${action('add-item',icon('plus')+'<span>Add</span>','add-product',`data-id="${o.offer_id}" aria-label="Add ${esc(o.product_name)}"`)}</article>`).join('')||'<div class="small-empty">No active products are available from Catalogue. Please try again later.</div>'}</div></div></section><section class="panel"><div class="panel-head"><h2>Selected items</h2><span class="result-count">${draft.items.reduce((s,i)=>s+(validQuantity(i.quantity)?i.quantity:0),0)} items</span></div>${itemsTable()}</section>`;
 else if(stage===2)content=`<section class="panel"><div class="panel-head"><div><h2>Who is receiving the order?</h2><p>Add the contact and delivery details.</p></div><span class="step-label">STEP 2 OF 3</span></div><div class="panel-body">${recipientFields()}</div></section>`;
 else content=`<section class="panel"><div class="panel-head"><div><h2>Review your order</h2><p>Your draft is saved. Check everything before submitting.</p></div><span class="step-label">STEP 3 OF 3</span></div><div class="panel-body">${reviewContent()}</div></section>`;
 shell(`<a class="back" href="#orders">${icon('back')}Back to ${isStaff()?'orders':'my orders'}</a><div class="page-head"><div><div class="eyebrow">${draft.order_id?'CONTINUE YOUR PURCHASE':'BUILD A PURCHASE'}</div><h1 tabindex="-1">${draft.order_id?'Edit draft':'Create an order'}</h1><p>Select items, add a recipient, and review the current prices.</p></div></div>${stageIndicator()}<p class="current-step" role="status">Step ${stage} of 3 — ${['Select items','Recipient details','Review order'][stage-1]}</p><div class="split draft-layout"><div>${content}<div class="stage-navigation" ${stage===3?'hidden':''}>${stage>1&&stage<3?action('stage',icon('back')+'Back','','data-stage="1"'):'<span></span>'}${stage<3?`<div class="actions">${action('save-draft','Save draft','secondary')}${action('stage-next',`Continue to ${stage===1?'recipient':'review'} ${icon('arrow')}`,'primary')}</div>`:''}</div></div>${summary()}</div>`,'new');
 if(focus)document.querySelector(focus)?.focus({preventScroll:true});
}
function validateDraft(recipient=false){captureDraft();const errors={};if(!draft.items.length)errors.items='Add at least one product to continue.';if(draft.items.some(i=>!Number.isSafeInteger(i.quantity)||i.quantity<1||i.quantity>100000))errors.items='Use positive whole-number quantities, up to 100,000.';if(draft.items.some(i=>!offers.some(o=>o.offer_id===i.offer_id&&o.seller_id===Number(draft.seller_id))))errors.items='An item is no longer available. Remove it or select an active offer.';if(recipient){if(!draft.customer_id)errors.customer_id='Select a customer for this order.';for(const [key,name]of [['recipient_name','recipient name'],['recipient_contact','contact number'],['requested_delivery_address','delivery address']])if(!String(draft[key]||'').trim())errors[key]=`Enter the ${name}.`;}if(errors.items){formError(errors.items);return false;}return showErrors(errors);}
async function persistDraft(){captureDraft();if(!isStaff())draft.customer_id=me.customer_id;if(!draft.customer_id)throw new Error('Choose or create a customer in Recipient details before saving.');const acknowledged=draftState();const result=await api(draft.order_id?'/orders/'+draft.order_id:'/orders',draft.order_id?'PUT':'POST',draft);draft.order_id=result.order_id;draft.version=result.version;baseline=acknowledged;order={...draft};return result;}
async function advanceStage(){if(stage===1){if(!validateDraft())return;stage=2;draftView();document.querySelector('#draft-form input')?.focus();}else if(stage===2){if(!validateDraft(true))return;await persistDraft();order=await api('/orders/'+draft.order_id);draft.order_total=order.order_total;quote=await api(`/orders/${order.order_id}/review`,'POST',{});stage=3;draftView();document.querySelector('main h2')?.scrollIntoView({block:'start'});}}
function orderProgress(o){let exception='';const issue=issueState(o);if(issue.status==='resolved')exception=`<div class="progress-exception issue-resolved"><strong>${issue.outcome==='cancelled'?'Order cancelled':'Order unsuccessful'} — Issue resolved</strong></div>`;else if(['draft','cancelled','cancellation_pending'].includes(o.order_status))exception= `<div class="progress-exception ${o.order_status==='draft'?'':'warning'}">${icon(o.order_status==='draft'?'orders':'alert')}<div><strong>${label(o.order_status)}</strong><p>${esc(nextStep(o,isStaff()))}</p>${o.order_status==='cancellation_pending'?`<div class="cancel-checks"><span>${cancellationChecks(o).unpaidVerified?icon('check'):icon('clock')}${cancellationChecks(o).paymentVerified?'Payment verified — reconciliation required':'Unpaid payment check: '+(cancellationChecks(o).unpaidVerified?'verified':'waiting')}</span><span>${cancellationChecks(o).releaseVerified?icon('check'):icon('clock')}Stock release: ${cancellationChecks(o).releaseVerified?'verified':'waiting'}</span></div>`:''}</div></div>`;return exception+`<ol class="order-progress" aria-label="Order progress">${milestones(o).map((m,i)=>`<li class="${m.done?'done':m.active?'current':''}"><span class="milestone">${m.done?icon('check'):i+1}</span><strong>${m.name}</strong><small>${m.state}</small>${m.explanation?`<small>${esc(m.explanation)}</small>`:''}</li>`).join('')}</ol>`;}
function historyReason(h){if(h.reason==='Inventory reserved stock for cash on delivery.')return h.reason;if(order?.payment_method==='cod'&&h.new_status==='completed')return 'Delivery and cash collection were verified by Delivery and Billing.';if(order?.payment_method==='cod'&&h.new_status==='confirmed'&&h.previous_status!==h.new_status)return 'Cash on delivery arrangement prepared and Inventory confirmed stock. No advance payment was required.';if(h.previous_status===h.new_status)return /^(Stock was|Payment was|Delivery |COD collection|The stock reservation|Processing paused\.)/.test(h.reason)?h.reason:'Processing stopped. Review the order outcome and contact the sales team.';if(isStaff()&&!String(h.reason).includes('proof:'))return h.reason;return {draft:'Your order draft was saved.',pending_stock:'Your order was submitted for stock confirmation.',awaiting_payment:'Inventory confirmed the reservation for all items.',confirmed:'Payment was verified and the stock reservation was confirmed.',fulfilling:'Delivery accepted your order.',completed:'Delivery was verified.',cancellation_pending:'Cancellation is waiting for payment checks and stock release.',cancelled:h.previous_status==='draft'?'Your draft was cancelled.':'Payment checks and stock release were verified.'}[h.new_status]||'Order progress updated.';}
function issuePanel(o,r){
 const issue=issueState(o,r);if(!issue.outcome)return '';
 const status={action_required:'Action required',in_progress:'In progress',resolved:'Resolved'}[issue.status];
 const reason=o.cancellation_reason||o.outcomes?.find(x=>/failed|rejected|expired/.test(x.kind))?.message||r.return_reason||'';
 const names={accept_cancel:'Accept cancellation',refund_start:'Start / retry refund',refund_record:'Record completed refund',return_transit:'Record return in transit',return_receive:'Confirm receipt / condition',stock_record:'Record Inventory evidence',clearance_check:'Check payment / stock clearance',external_evidence:'Document external settlement or a not-applicable decision below'};
 return `<div class="issue-summary ${issue.status==='resolved'?'issue-resolved':''}"><p><strong>Order status:</strong> ${issue.outcome==='cancelled'?'Cancelled':'Unsuccessful'}</p><p><strong>Issue status:</strong> ${status}</p>${reason?`<p><strong>Original outcome reason:</strong> ${esc(reason)}</p>`:''}${issue.reopened?'<p class="note warning">New order facts were received after closure. Review the requirements and record a new resolution.</p>':''}${issue.status==='resolved'?`<h3>${issue.outcome==='cancelled'?'Order cancelled':'Order unsuccessful'} — Issue resolved</h3><p>${esc(r.issue_note)}</p><p>Resolved by admin ${r.issue_admin_id} · ${date(r.issue_at,true)}${r.issue_reference?' · Reference: '+esc(r.issue_reference):''}</p>${Object.entries(r.issue_dispositions||{}).map(([key,x])=>`<article><strong>${esc(label(key))}: ${x.status==='not_applicable'?'Documented as not applicable':'Externally completed — evidence recorded'}</strong><p>${esc(x.note)} · Reference: ${esc(x.reference)}</p></article>`).join('')}<p>Closure preserves the original payment, delivery, return and stock records.</p>`:`<h3>Requirements before closure</h3>${r.issue_requirements.length?`<ul>${r.issue_requirements.map(x=>`<li>${esc(x.label)} ${r.actions?.includes(x.action)?action('issue-requirement-action',names[x.action],'link',`data-resolution-action="${x.action}"`):x.action==='clearance_check'&&me.role==='staff'?action('check-clearance',names[x.action],'link'):`<span>${esc(names[x.action])}. The responsible team can provide evidence for closure.</span>`}</li>`).join('')}</ul>`:'<p>All applicable requirements are complete. Record a resolution note and confirm closure.</p>'}${me.role==='staff'?action('begin-issue-closure','Mark issue as resolved','primary'):''}`}</div>`;
}

function resolutionPanel(o){
 const r=o.resolution;if(!r||o.order_status==='draft')return '';const issue=issueState(o,r);
 const labels={mark_resolved:'Mark issue as resolved',accept_cancel:'Accept cancellation',refund_start:'Start / retry refund',refund_fail:'Record refund failure',refund_record:'Record completed refund (external payment)',return_required:o.order_status==='confirmed'&&!o.tracking_reference?'Stop fulfillment — release reservation':'Stop fulfillment — return to seller',return_transit:'Record return in transit',return_receive:'Confirm seller receipt and condition',stock_record:'Record Inventory restoration evidence'};
 const states={none:'No refund required',required:'Refund required',processing:'Refund processing',failed:'Refund failed — retry required',recorded:'Refund recorded'};
 const returnNames={none:'No return requested',not_dispatched:'Goods did not leave seller — no physical return',required:'Return required',in_transit:'Return in transit',received:'Received by seller',issue:'Missing / unconfirmed — review required'};
 const stockNames={none:'No stock restoration recorded',release_pending:'Inventory reservation release pending',released:'Reservation release verified by Inventory',inventory_pending:'Inventory confirmation pending',demo_restored:'Eligible stock restored in demo Inventory ledger',restoration_recorded:'Inventory restoration recorded from external evidence',condition_review:'Stock unresolved — condition review required'};
 const visible=r.cancel_accepted||r.fulfillment_stopped||r.needs_resolution||o.shipment==='failed'||o.payment==='failed'||['cancelled','cancellation_pending'].includes(o.order_status)||isStaff();if(!visible)return '';
 const actions=r.actions||[];
 return `<section class="panel resolution-panel"><div class="panel-head"><h2>Refund and return resolution</h2></div><div class="panel-body">${issuePanel(o,r)}${issue.status==='resolved'?'<p>Source payment and refund records below are unchanged; see the closure note and any external evidence above.</p>':''}<h3>${issue.status==='resolved'&&o.payment==='failed'?'Original payment verification: Failed (preserved)':o.payment==='verified'?states[r.refund_status]:o.payment_method==='cod'?'No payment collected — No refund required':'No verified payment — No refund required'}</h3>${r.release_pending&&issue.status!=='resolved'?`<p class="note warning">Inventory reservation release is pending.</p>${me.role==='staff'?action('check-clearance','Check payment / stock clearance','secondary'):''}`:''}<dl class="resolution-facts"><div><dt>Original payment</dt><dd>${esc(paymentMethodLabel(o.payment_method))} · ${peso(r.paid_amount)}<br>${esc(o.transaction_reference||o.invoice_reference||'No verified payment reference')}</dd></div><div><dt>${issue.status==='resolved'?'Source refundable balance':'Remaining refundable amount'}</dt><dd>${peso(r.refundable_amount)}</dd></div><div><dt>Refund method / reason</dt><dd>${esc(r.refund_method||'Not selected')} · ${esc(r.refund_reason||r.reason||'No refund requested')}</dd></div><div><dt>Return status</dt><dd>${returnNames[r.return_status]}<br>${esc(r.return_reason||'')}${r.return_party?'<br>Responsible party: '+esc(r.return_party):''}${r.return_reference?'<br>Tracking: '+esc(r.return_reference):''}</dd></div><div><dt>Receipt and stock</dt><dd>${esc(r.condition||'Condition not confirmed')} · ${stockNames[r.stock_status]}${r.receipt_reference?'<br>Receipt reference: '+esc(r.receipt_reference):''}</dd></div></dl>${issue.status!=='resolved'&&r.refund_failure&&r.refund_status==='failed'?`<p class="note warning">Last refund failure: ${esc(r.refund_failure)}</p>`:''}${r.return_required_at?'<p>Return required: '+date(r.return_required_at,true)+'</p>':''}${r.return_transit_at?'<p>In transit: '+date(r.return_transit_at,true)+'</p>':''}${r.received_at?'<p>Receipt recorded: '+date(r.received_at,true)+'</p>':''}
 ${r.refunds.length?`<h3>Recorded refunds</h3>${r.refunds.map(x=>`<article class="order-message"><strong>${peso(x.amount)} · ${esc(x.method)}</strong><p>Reference: ${esc(x.reference)} · ${date(x.created_at,true)} · Recorded by user ${x.actor_id}</p><p>${esc(x.evidence)}</p></article>`).join('')}`:''}
 ${actions.length?`<form id="resolution-form" novalidate data-order-id="${o.order_id}" data-request-id="${crypto.randomUUID()}"><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Available resolution action<select name="action" id="resolution-action">${actions.map(a=>`<option value="${a}">${labels[a]}</option>`).join('')}</select></label><div class="issue-dispositions" hidden>${(r.issue_requirements||[]).map(x=>`<fieldset data-issue-requirement="${x.key}"><legend>${esc(x.label)}</legend><label>How was this addressed?<select data-disposition-status><option value="">Complete the action first, or document an exception</option><option value="externally_completed">Completed externally — evidence recorded</option><option value="not_applicable">Not applicable — documented decision</option></select></label><label>Explanation<textarea data-disposition-note maxlength="1000"></textarea></label><label>External reference or evidence<input data-disposition-reference maxlength="150"></label></fieldset>`).join('')}</div><label data-resolution-field="method" hidden>Refund method<select name="method"><option value="gcash">GCash</option><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option></select></label><label data-resolution-field="amount" hidden>Amount (PHP)<input name="amount" type="number" min="0.01" step="0.01" max="${esc(r.refundable_amount)}" value="${esc(r.refundable_amount)}"></label><label data-resolution-field="reference" hidden>Transaction / handover / receipt reference<input name="reference" maxlength="100"></label><label data-resolution-field="party" hidden>Responsible delivery party<input name="party" maxlength="150"></label><label data-resolution-field="condition" hidden>Condition<select name="condition"><option value="saleable">Received — saleable</option><option value="damaged">Received — damaged</option><option value="missing">Missing / not confirmed</option></select></label><label>Reason and supporting evidence<textarea name="reason" maxlength="2000" rows="3" required></textarea></label><label class="check" data-resolution-field="not_received" hidden><input name="not_received" type="checkbox"><span>Delivery evidence confirms the customer did not receive the goods. Preserve the original event in history and correct the current outcome.</span></label><label class="check" data-resolution-field="confirmed" hidden><input name="confirmed" type="checkbox"><span data-resolution-confirm-text>I confirm this action and its evidence. For a refund, payment was completed outside this application. For receipt or restoration, the responsible party has confirmed it.</span></label><p class="field-hint">Recording a refund does not transfer money. ${config.demo?'Delivery and stock actions use the demo ledger.':'Delivery and Inventory evidence must come from the responsible module.'}</p><button class="primary" type="submit">Save resolution action</button></form>`:r.needs_resolution?'<p class="note warning">Awaiting the responsible Billing, Delivery or Inventory role. Check the latest evidence and contact Sales using this order conversation.</p>':''}
 ${r.history.length?`<details><summary>Resolution history (${r.history.length})</summary><ol class="timeline">${r.history.map(h=>`<li><strong>${labels[h.action]||esc(h.action)}</strong><time>${date(h.created_at,true)}</time><p>${esc(JSON.parse(h.details).reason)} · ${esc(h.actor_role)} user ${h.actor_id}</p></li>`).join('')}</ol></details>`:''}</div></section>`;
}
function resolutionSelection(){
 const form=document.querySelector('#resolution-form');if(!form)return;const a=form.elements.action.value;form.querySelector('button[type="submit"]').textContent=a==='mark_resolved'?'Confirm issue resolved':'Save resolution action';form.querySelector('.issue-dispositions').hidden=a!=='mark_resolved';
 const fields={method:a==='refund_start',amount:a==='refund_record',reference:['mark_resolved','refund_record','return_transit','return_receive','stock_record'].includes(a)||a==='return_required'&&order?.shipment==='delivered',party:a==='return_transit',condition:a==='return_receive',not_received:a==='return_required'&&order?.shipment==='delivered',confirmed:['mark_resolved','accept_cancel','refund_record','return_required','return_receive','stock_record'].includes(a)};
 for(const [name,visible]of Object.entries(fields)){const label=form.querySelector('[data-resolution-field="'+name+'"]');label.hidden=!visible;form.elements[name].required=visible;}form.querySelector('[data-resolution-confirm-text]').textContent=a==='mark_resolved'?'I confirm issue closure and the documented treatment of every requirement. This action does not issue a refund or change payment, delivery, return or stock records.':'I confirm this action and its evidence. For a refund, payment was completed outside this application. For receipt or restoration, the responsible party has confirmed it.';
}

function outcomePanel(o){
 const end=processingEnd(o),complete=o.order_status==='completed',retry=o.shipment==='failed'&&!end.finished,scheduled=retry&&o.requests.some(r=>r.service==='delivery'&&!['done','blocked'].includes(r.status));
 if(!end.finished&&!complete&&!retry)return '';
 const resolution=issueState(o).status==='resolved'?'Issue closure is recorded above. The original order outcome is preserved.':complete?'Delivery and payment confirmed.':scheduled?'The agreed redelivery schedule is recorded below. Waiting for the next Delivery result.':retry?'Arrange another delivery time with Sales. No additional payment is required for an already paid order.':o.resolution?.needs_resolution?'Use Refund and return resolution above for the remaining actions.':o.order_status==='cancellation_pending'?'Payment checks and stock release are pending.':'Processing has ended. Contact Sales if you need help with the recorded outcome.';
 return `<section class="panel"><div class="panel-head"><h2>Order outcome and next steps</h2></div><div class="panel-body"><strong>${complete?'Order completed':scheduled?'Redelivery scheduled':retry?'Delivery needs rescheduling':esc(end.title)}</strong><p>${complete?'Your order was delivered and payment was confirmed.':retry?'This delivery attempt failed. The order remains active for redelivery.':esc(end.explanation)}</p><p><strong>Resolution:</strong> ${esc(resolution)}</p>${!retry&&!isStaff()?action('order-again','Order again','secondary'):''}<p>Use Contact Sales below for follow-up. A new order checks current prices and availability.</p></div></section>`;
}
function rescheduleForm(o){
 if(me.role!=='staff'||o.shipment!=='failed'||processingEnd(o).finished)return '';
 if(o.requests.some(r=>r.service==='delivery'&&!['done','blocked'].includes(r.status)))return '<p class="note">Redelivery is scheduled. Delivery can be checked at the agreed time; payment remains unchanged.</p>';
 return `<form id="reschedule-form"><h3>Schedule redelivery</h3><div class="error" data-form-error role="alert" hidden></div><label>Agreed redelivery date and time<input type="datetime-local" name="scheduled_at" step="1" required></label><label>Customer agreement and delivery details<textarea name="reason" maxlength="1000" required></textarea></label><p class="field-hint">Confirm the schedule with the customer through the conversation below. Times use your device’s local timezone.</p><button type="submit" class="primary">Schedule redelivery</button></form>`;
}

function communicationPanels(o){
 const active=['confirmed','fulfilling'].includes(o.order_status)&&!processingEnd(o).finished&&!o.reconciliation&&o.shipment!=='delivered';
 return `<section class="panel"><div class="panel-head"><h2>Delivery updates</h2></div><div class="panel-body">${o.delivery_updates?.map(u=>`<article class="delivery-notice"><strong>${u.kind==='rescheduled'?'Redelivery scheduled':u.kind==='delayed'?'Delivery delayed':'Delay cleared'}</strong><p>${esc(u.reason)}</p><p>${u.estimated_at?'Estimated delivery: '+date(u.estimated_at,true):u.kind==='delayed'?'Awaiting an updated delivery estimate.':''}</p>${u.next_update_at?'<p>Next update by '+date(u.next_update_at,true)+'</p>':''}<small>Sales update · ${date(u.created_at,true)}</small></article>`).join('')||'<p>No delivery updates yet.</p>'}${rescheduleForm(o)}${me.role==='staff'&&active&&o.shipment!=='failed'?`<form id="delivery-update-form"><div class="error" data-form-error role="alert" hidden></div><label>Delivery update<select name="kind"><option value="delayed">Report delivery delay</option>${o.delivery_updates?.[0]?.kind==='delayed'?'<option value="resumed">Clear delivery delay</option>':''}</select></label><label>Reason / update for the customer<textarea name="reason" maxlength="1000" required></textarea></label><label>Revised delivery estimate (optional)<input type="datetime-local" name="estimated_at"></label><label>Next update expected by (optional)<input type="datetime-local" name="next_update_at"></label><p class="field-hint">Use information confirmed with Delivery. Times use your device’s local timezone. This notice does not confirm delivery.</p><button class="primary" type="submit">Publish delivery update</button></form>`:''}</div></section><section class="panel" id="sales-conversation"><div class="panel-head"><h2>${isStaff()?'Customer conversation':'Contact Sales'}</h2></div><div class="panel-body"><p>Messages are linked to this order. ${isStaff()?'Reply below; the customer receives an in-app notification.':'Send your question below. Check this order or Notifications for a Sales reply.'}</p>${o.messages?.map(m=>`<article class="order-message"><strong>${m.sender_role==='staff'?'Sales team':'Customer'}</strong><time>${date(m.created_at,true)}</time><p>${esc(m.body)}</p></article>`).join('')||'<p>No messages yet.</p>'}${!isStaff()||me.role==='staff'?`<form id="message-form"><div class="error" data-form-error role="alert" hidden></div><label>${isStaff()?'Reply to customer':'Message to Sales'}<textarea name="body" maxlength="2000" required rows="3"></textarea></label><button class="primary" type="submit">${isStaff()?'Send reply':'Send message'}</button></form>`:''}</div></section>`;
}

function detailView(){const o=order,expired=stockExpired(o);
 shell(`<a class="back" href="#orders">${icon('back')}Back to ${isStaff()?'orders':'my orders'}</a><div class="page-head"><div><div class="eyebrow">${isStaff()?'ORDER DETAILS':'YOUR PURCHASE'}</div><h1 class="order-heading" tabindex="-1">${esc(o.order_number)}</h1><p>Created ${date(o.created_at,true)}${isStaff()?' · '+esc(o.customer_name):''}</p></div>${orderBadge(o)}</div><div class="next-step-banner ${issueState(o).status!=='resolved'&&(o.reconciliation||expired)?'warning':''}">${icon(issueState(o).status==='resolved'?'check':o.reconciliation||expired?'alert':'clock')}<span><strong>${issueState(o).status==='resolved'?'Issue resolved':o.reconciliation?'Order needs attention':'What happens next'}</strong>${esc(nextStep(o,isStaff()))}</span>${action('refresh',icon('refresh')+'Refresh','quiet')}</div>${resolutionPanel(o)}${outcomePanel(o)}${communicationPanels(o)}<section class="panel progress-panel"><div class="panel-head"><h2>Order progress</h2><small>Based on verified service updates</small></div><div class="panel-body">${orderProgress(o)}</div></section><div class="split detail-layout"><div><section class="panel"><div class="panel-head"><div><h2>Purchased items</h2><p>${esc(o.seller_name)}</p></div><span class="result-count">${o.items.reduce((s,i)=>s+i.quantity,0)} items</span></div><div class="purchase-items">${o.items.map(i=>`<div class="purchase-item">${thumbnail(i)}<div><strong>${esc(i.product_name_at_order)}</strong><small>${i.quantity} × ${peso(i.unit_price_at_order)}${isStaff()?' · Offer #'+i.offer_id:''}</small></div><strong>${peso(cents(i.unit_price_at_order)*i.quantity/100)}</strong></div>`).join('')||'<div class="small-empty">This draft has no items yet.</div>'}</div><div class="panel-body purchase-total"><div class="summary-row total"><span>Product total</span><strong>${peso(o.order_total)}</strong></div><p class="money-note">${o.order_status==='draft'?'Draft estimate. Current prices are checked before submission.':'Accepted product names and prices are saved with this purchase.'} No additional charges.</p></div></section><section class="panel"><div class="panel-head"><h2>Stock, payment & delivery</h2><small>Separate service confirmations</small></div><div class="facts"><div class="fact"><span class="fact-icon">${icon('box')}</span><h3>Stock reservation</h3>${badge(expired?'expired':o.stock)}<p>${o.reservation_expires?`${o.order_status==='completed'?'Reservation validity at purchase':['released','expired'].includes(o.stock)?'Original reservation deadline':'Valid until'} ${date(new Date(Number(o.reservation_expires)).toISOString(),true)}`:o.stock==='confirmed'?'Confirmed hold — no automatic expiry.':o.stock==='fulfilled'?'Stock deduction verified by Inventory.':'No stock reservation has been confirmed.'}</p></div><div class="fact"><span class="fact-icon">${icon('card')}</span><h3>Payment</h3><strong>${esc(paymentMethodLabel(o.payment_method))}</strong>${badge(o.payment)}<p>${esc(o.invoice_reference||'No invoice has been created.')}${o.transaction_reference?'<br>'+esc(o.transaction_reference):''}</p></div><div class="fact"><span class="fact-icon">${icon('truck')}</span><h3>Shipment</h3>${badge(o.shipment)}<p>${esc(o.tracking_reference||'No shipment has been confirmed.')}</p></div></div></section><section class="panel"><div class="panel-head"><h2>Status history</h2><span class="result-count">${o.history.length} updates</span></div><div class="panel-body"><ol class="timeline">${o.history.map(h=>`<li><div><strong>${label(h.new_status)}</strong><time>${date(h.changed_at,true)}</time></div><p>${esc(historyReason(h))}</p>${isStaff()?`<small>Source: ${esc(h.change_source)}</small>`:''}</li>`).join('')}</ol></div></section></div><aside><section class="panel"><div class="panel-head"><h2>Recipient details</h2>${icon('user')}</div><div class="panel-body detail-meta"><strong>${esc(o.recipient_name||'Not entered')}</strong><span>${esc(o.recipient_contact||'No contact number entered')}</span><p>${esc(o.requested_delivery_address||'No address entered')}</p>${isStaff()?`<div class="contact-block"><small>CUSTOMER</small><strong>${esc(o.customer_name)}</strong><span>${esc(o.contact_number)}</span></div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Available actions</h2></div><div class="panel-body detail-actions">${o.order_status==='draft'?`${link('#edit/'+o.order_id,'Continue draft','primary full')}${action('review','Review & submit','secondary full')}`:''}${action('refresh',icon('refresh')+'Refresh progress','full')}${canCancel(o)&&['staff','customer'].includes(me.role)?action('cancel','Cancel order','danger full'):''}${config.demo&&me.role==='staff'&&!['draft','cancelled','completed'].includes(o.order_status)?link('#operations','Processing outcomes','quiet full'):''}${o.cancellation_reason?`<div class="cancellation-reason"><small>CANCELLATION REASON</small><p>${esc(o.cancellation_reason)}</p></div>`:''}</div></section></aside></div>`);
}

document.addEventListener('input',event=>{if(event.target.id==='operation-search'){operationSearch=event.target.value;operationLimit=8;renderOperationChoices();}});
function notificationCards(rows){return rows.map(n=>`<article class="notification-card ${n.read_at?'':'unread'}"><div><strong>${esc(n.order_number)}</strong><span class="notification-state">${n.read_at?'Read':'Unread'}</span><p>${esc(n.message)}</p><time>${date(n.created_at,true)}</time></div><div class="actions">${link('#order/'+n.order_id,'View order and next steps','secondary')}${!n.read_at?action('read-notification','Mark as read','quiet',`data-id="${n.notification_id}"`):''}</div></article>`).join('');}
function notificationsView(){shell(`<div class="page-head"><div><div class="eyebrow">YOUR ACCOUNT</div><h1 tabindex="-1">Notifications</h1><p>Order outcomes and cancellation updates stay here after you sign in again.</p></div></div><section class="panel"><div class="panel-body">${notifications.length?notificationCards(notifications):'<p>No order updates yet.</p>'}</div></section>`,'notifications');}
function outcomeSelection(){const form=document.querySelector('#outcome-form');if(!form)return;const value=form.elements.outcome.value,needsReason=['unsuccessful','cancel','reattempt'].includes(value);form.querySelector('.outcome-reason').hidden=!needsReason;form.elements.reason.required=needsReason;form.querySelector('.retry-schedule').hidden=value!=='reattempt';form.elements.scheduled_at.required=value==='reattempt';form.querySelector('.outcome-explanation').textContent=currentProcessing.options.find(x=>x.value===value)?.explanation||'Choose the result for this stage.';form.querySelector('button[type="submit"]').disabled=!value;}
function operationMatches(o,filter){return filter==='all'||filter==='draft'&&o.order_status==='draft'||filter==='attention'&&o.work.attention||filter==='pending'&&o.work.pending||filter==='closed'&&o.work.closed;}
function renderOperationChoices(){
 const results=document.querySelector('#operation-results'),select=document.querySelector('#operation-order');if(!results||!select)return;
 const term=operationSearch.trim().toLowerCase();
 const rows=operationChoices.filter(o=>operationMatches(o,operationFilter)&&`${o.order_number} ${o.customer_name}`.toLowerCase().includes(term));
 results.innerHTML=`<p class="operation-count">${rows.length} matching orders${rows.some(o=>o.order_id===operationOrderId)?'':' · Selected order below is outside these results'}</p><div class="operation-cards">${rows.slice(0,operationLimit).map(o=>`<article class="operation-card ${o.order_id===operationOrderId?'selected':''}"><div><strong>${esc(o.customer_name)}</strong><small>${esc(o.order_number)}</small></div><span class="badge ${o.work.attention?'badge-warning':''}">${o.work.attention?'Needs attention':o.work.pending?'Pending':esc(label(o.order_status))}</span><p>${esc(o.work.step)}</p>${o.work.reason?`<p class="operation-reason">${esc(o.work.reason)}</p>`:''}${action('operation-pick',o.order_id===operationOrderId?'Selected — view below':'Review order','secondary',`data-id="${o.order_id}" ${o.order_id===operationOrderId?'aria-current="true"':''}`)}</article>`).join('')}</div>${rows.length>operationLimit?action('operation-more','Show more orders','quiet'):''}${!rows.length?'<p>No orders match. Try another customer or choose All orders.</p>':''}`;
 select.innerHTML='<option value="">Select an order to review</option>'+rows.map(o=>`<option value="${o.order_id}"${selected(o.order_id,operationOrderId)}>${esc(o.customer_name)} · ${esc(o.order_number)} · ${o.work.attention?'Needs attention · ':''}${esc(o.work.step)}</option>`).join('');
 select.value=rows.some(o=>o.order_id===operationOrderId)?String(operationOrderId):'';
}

async function operations(requests,ticket){
 const orders=await api('/orders');
 operationChoices=orders.map(o=>({...o,work:operationSummary(o,requests)})).sort((a,b)=>a.work.priority-b.work.priority||a.order_id-b.order_id);
 if(!orders.some(o=>o.order_id===operationOrderId))operationOrderId=operationChoices[0]?.order_id;
 const o=operationOrderId?await api('/orders/'+operationOrderId):null;
 const stage=o?await api('/orders/'+o.order_id+'/processing'):null;
 if(ticket!==epoch)return;
 currentProcessing=stage;
 shell(`<div class="page-head"><div><div class="eyebrow">SALES WORKSPACE</div><h1 tabindex="-1">Processing outcome</h1><p>Review the current stage and record its allowed outcome.</p></div>${action('refresh',icon('refresh')+'Refresh')}</div>
 ${config.demo?'':'<p class="note">Inventory, Billing and Delivery provide verified results. Staff can check for updates or request an eligible cancellation.</p>'}
 <section class="panel"><div class="panel-head"><div><h2>Orders to review</h2><p>Needs attention first, then pending orders. Select a customer’s order to review its current step.</p></div></div><div class="panel-body"><div class="operation-filters"><label>Find order or customer<input id="operation-search" type="search" value="${esc(operationSearch)}" placeholder="Order number or customer" aria-controls="operation-results operation-order"></label><label>Show<select id="operation-filter">${[['all','All orders'],['attention','Needs attention'],['pending','Pending processing'],['closed','Ended / completed']].map(([v,t])=>`<option value="${v}"${selected(v,operationFilter)}>${t} (${operationChoices.filter(o=>operationMatches(o,v)).length})</option>`).join('')}</select></label></div><p class="field-hint">Showing all permitted orders. Pending orders are still active; attention also includes customer messages and unresolved checks.</p><div id="operation-results" aria-live="polite"></div><label>Choose order<select id="operation-order"></select></label></div></section>
 ${o?`<section class="panel" id="processing-selected"><div class="panel-body"><div class="actions"><h2>${esc(o.order_number)}</h2>${orderBadge(o)}</div><p>${esc(o.customer_name)} · ${peso(o.order_total)} · ${esc(paymentMethodLabel(o.payment_method))}</p><p>${link('#order/'+o.order_id,'View order details and resolution actions')}</p><p class="processing-feedback">${esc(nextStep(o,true))}</p>${orderProgress(o)}<p class="service-summary">Stock: ${esc(label(o.stock))} · Payment: ${esc(label(o.payment))} · Delivery: ${esc(label(o.shipment))}</p></div></section>
 <section class="panel ${stage.processing_finished?'processing-closed':''}"><div class="panel-body"><h2>${stage.processing_finished?'Processing ended — '+esc(stage.condition):'Current stage: '+esc(stage.stage)}</h2>${stage.guidance?`<p class="stage-guidance">${esc(stage.guidance)}</p>`:''}${stage.options.length?`<form id="outcome-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Processing outcome<select name="outcome" id="processing-outcome" required>${stage.options.map(x=>`<option value="${x.value}">${x.label}</option>`).join('')}</select></label><p class="outcome-explanation" aria-live="polite">Choose the result for this stage.</p><label class="retry-schedule" hidden>Agreed next delivery date and time<input type="datetime-local" name="scheduled_at" step="1"><span class="field-hint">Confirm this schedule with the customer. Times use your device’s local timezone.</span></label><label class="outcome-reason" hidden>Reason shown to the customer<textarea name="reason" maxlength="1000" rows="3" aria-describedby="error-outcome-reason"></textarea><span class="field-error" data-error-for="reason" id="error-outcome-reason" role="alert"></span></label><button type="submit" class="primary" disabled>Apply outcome</button></form>`:`<p>${stage.processing_finished?'Normal fulfillment has stopped. Open order details for refund, return and stock resolution actions.':o.order_status==='draft'?'Submit this draft before processing.':stage.can_query?'Waiting for a verified service result.':o.shipment==='failed'?'Use order details to review or arrange redelivery.':'No further action available'}</p>`}
 ${stage.unresolved&&!stage.processing_finished?'<p class="note warning">The previous result is unresolved. Check again using the same stage; it has not been marked unsuccessful.</p>':''}
 ${stage.processing_finished&&stage.resolution_pending?`<div class="resolution-note"><p>Payment checks or stock release remain under review. These are resolution tasks; the order will not proceed to shipment or delivery.</p>${action('resolve-stopped',config.demo?'Retry resolution checks':'Check resolution updates','secondary')}</div>`:''}
 ${stage.can_query?action('dispatch','Check service update','secondary',`data-ref="${esc(stage.request_reference)}"`):''}</div></section>
 <details class="panel"><summary>Order history (${o.history.length})</summary><div class="panel-body"><ol class="timeline">${o.history.map(h=>`<li><strong>${label(h.new_status)}</strong><p>${esc(historyReason(h))}</p><time>${date(h.changed_at,true)}</time></li>`).join('')}</ol></div></details>`:'<section class="panel"><div class="panel-body"><p>No orders yet. Submitted customer orders will appear here.</p></div></section>'}`,'operations');
 renderOperationChoices();
 outcomeSelection();
}


function openModal(title,content){modal.setAttribute('aria-labelledby','modal-title');modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${action('close-modal',icon('close'),'icon-button','aria-label="Close dialog"')}</div>${content}`;modal.showModal();}
async function review(){quote=await api(`/orders/${order.order_id}/review`,'POST',{});openModal('Review your order',`<p>Confirm the recipient and current purchase details.</p>${reviewContent(true)}`);}
async function submitOrder(){if(busy.has('review-payment')||!quote)return formError('Wait for the payment choice to be saved and reviewed.',modal.open?modal:document);const accepted=document.querySelector('#accept-prices');if(!accepted?.checked)return formError('Accept the current prices to continue.');const key=`submit:${order.order_id}:${quote.version}`;let ref=sessionStorage.getItem(key);if(!ref){ref=crypto.randomUUID();sessionStorage.setItem(key,ref);}try{await api(`/orders/${order.order_id}/submit`,'POST',{submission_reference:ref,version:quote.version,acceptance:quote.acceptance});draftActive=false;modal.close();toast('Order submitted. Waiting for stock confirmation.');if(location.hash===`#order/${order.order_id}`)await route();else location.hash=`order/${order.order_id}`;}catch(error){if(error.details?.quote){quote=error.details.quote;if(modal.open){openReviewAgain();}else{draftView();}formError('The names or prices changed. Review the revised details and accept them again.',modal.open?modal:document);}else formError(error.message,modal.open?modal:document);}}
function openReviewAgain(){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">Review updated prices</h2>${action('close-modal',icon('close'),'icon-button','aria-label="Close dialog"')}</div>${reviewContent(true)}`;}
function cancellationDialog(){openModal('Cancel this order?',`<p>${order.order_status==='draft'?'Your draft will be marked cancelled and kept in your order history.':'We’ll request payment checks and stock release. Cancellation stays pending until both are verified.'}</p><form id="cancel-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Reason for cancellation<textarea name="reason" required maxlength="1000" placeholder="Tell us why you want to cancel" aria-describedby="error-reason"></textarea>${fieldError('reason')}</label><div class="actions modal-actions">${action('close-modal','Keep order')}<button type="submit" class="danger">${order.order_status==='draft'?'Cancel draft':'Request cancellation'}</button></div></form>`);}
function customerDialog(){captureDraft();openModal('Add a customer',`<p>Save the contact details for this order.</p><form id="customer-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Customer name<input name="customer_name" required maxlength="150" autocomplete="name" aria-describedby="error-customer_name">${fieldError('customer_name')}</label><label>Email <span class="optional">Optional</span><input name="email" type="email" maxlength="255" autocomplete="email" aria-describedby="error-email">${fieldError('email')}</label><label>Contact number<input name="contact_number" required maxlength="30" type="tel" autocomplete="tel" aria-describedby="error-contact_number">${fieldError('contact_number')}</label><div class="actions modal-actions">${action('close-modal','Cancel')}<button type="submit" class="primary">Create customer</button></div></form>`);}
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target,button=form.querySelector('button[type="submit"]');
 try{
  if(form.id==='register-form'){await processing('login',button,async()=>{const data=Object.fromEntries(new FormData(form));const result=await api('/register','POST',data);me=result.user;csrf=result.csrf;page=1;sessionStorage.removeItem('orderFilters');if(location.hash==='#profile')await route();else location.hash='profile';},'Creating account…');}
  if(form.id==='outcome-form'){
    const data=Object.fromEntries(new FormData(form));
    if(!data.outcome)return formError('Choose an outcome.',form);
    if(data.outcome==='reattempt'){if(!data.scheduled_at||!Number.isFinite(Date.parse(data.scheduled_at)))return formError('Choose the agreed next delivery date and time.',form);data.scheduled_at=new Date(data.scheduled_at).toISOString();}
    if(['unsuccessful','cancel','reattempt'].includes(data.outcome)&&!data.reason.trim()){showErrors({reason:'Enter a reason shown to the customer.'},form);return;}
    await processing('dispatch',button,async()=>{try{const result=await api('/orders/'+operationOrderId+'/outcome','POST',{...data,version:currentProcessing.version,request_reference:currentProcessing.request_reference});await route();toast(result.pending?'Result unresolved. Check again later.':'Outcome recorded');}catch(error){formError(error.message,form);}},'Applying outcome…');
  }
  if(form.id==='overview-filter-form'){
    const data=Object.fromEntries(new FormData(form));if(data.period==='custom'&&(!data.from||!data.to||data.from>data.to))return formError('Choose a valid start and end date.',form);overviewFilters=data.period==='custom'?data:{period:data.period};sessionStorage.setItem('overviewFilters',JSON.stringify(overviewFilters));await processing('overview-filter',button,route,'Loading…');
  }
  if(form.id==='resolution-form'){
    await processing('resolution',button,async()=>{try{const data=Object.fromEntries(new FormData(form));data.confirmed=form.elements.confirmed.checked;data.not_received=form.elements.not_received.checked;if(data.action==='mark_resolved'){data.dispositions={};for(const box of form.querySelectorAll('[data-issue-requirement]'))data.dispositions[box.dataset.issueRequirement]={status:box.querySelector('[data-disposition-status]').value,note:box.querySelector('[data-disposition-note]').value,reference:box.querySelector('[data-disposition-reference]').value};}data.request_id=form.dataset.requestId;data.version=order.resolution.version;data.order_version=order.version;await api('/orders/'+form.dataset.orderId+'/resolution','POST',data);await route();toast('Resolution action recorded.');}catch(error){formError(error.message,form);}},'Saving resolution…');
  }
  if(form.id==='reschedule-form'){await processing('reschedule',button,async()=>{try{const data=Object.fromEntries(new FormData(form));data.scheduled_at=new Date(data.scheduled_at).toISOString();data.version=order.version;await api('/orders/'+order.order_id+'/reschedule','POST',data);await route();toast('Redelivery scheduled.');}catch(error){formError(error.message,form);}},'Scheduling…');}
  if(['message-form','delivery-update-form'].includes(form.id)){
    await processing('communication',button,async()=>{try{const data=Object.fromEntries(new FormData(form));for(const key of ['estimated_at','next_update_at'])if(data[key])data[key]=new Date(data[key]).toISOString();await api('/orders/'+order.order_id+(form.id==='message-form'?'/messages':'/delivery-updates'),'POST',data);await route();toast(form.id==='message-form'?'Message sent.':'Delivery update published.');}catch(error){formError(error.message,form);}},'Sending…');
  }
  if(form.id==='profile-form'){await processing('profile',button,async()=>{profile=await api('/profile','PUT',Object.fromEntries(new FormData(form)));profileView();toast('Profile saved. New orders will use these details.');},'Saving…');}
  if(form.id==='login-form'){if(busy.has('login'))return;const data=Object.fromEntries(new FormData(form)),errors={};if(!data.email?.trim()||!/^\S+@\S+\.\S+$/.test(data.email))errors.email='Enter a valid email address.';if(!data.password)errors.password='Enter your password.';if(!showErrors(errors,form))return;formError('',form);await processing('login',button,async()=>{try{await signIn(data.email,data.password);}catch(error){formError(error.message,form);form.querySelector('[name="password"]').value='';form.querySelector('[name="password"]').focus();}},'Signing in…');}
  if(form.id==='filter-form'){const params=new URLSearchParams();for(const[k,v]of new FormData(form))if(v.trim())params.set(k,v.trim());if(params.get('from')&&params.get('to')&&params.get('from')>params.get('to')){document.querySelector('[data-error-for="dates"]').textContent='The end date must be on or after the start date.';return;}page=1;sessionStorage.setItem('orderFilters',params.toString());await route();}
  if(form.id==='customer-form'){const data=Object.fromEntries(new FormData(form)),errors={};if(!data.customer_name.trim())errors.customer_name='Enter the customer name.';if(!data.contact_number.trim())errors.contact_number='Enter a contact number.';if(data.email&&!/^\S+@\S+\.\S+$/.test(data.email))errors.email='Enter a valid email address.';if(!showErrors(errors,form))return;await processing('customer',button,async()=>{try{const result=await api('/customers','POST',data);customers=await api('/customers');draft.customer_id=result.customer_id;modal.close();draftView('[name="customer_id"]');toast('Customer added.');}catch(error){formError(error.message,form);}},'Saving customer…');}
  if(form.id==='cancel-form'){const data=Object.fromEntries(new FormData(form));if(!showErrors(data.reason.trim()?{}:{reason:'Enter a cancellation reason.'},form))return;await processing('cancel',button,async()=>{try{await api(`/orders/${order.order_id}/cancel`,'POST',data);modal.close();await route();toast('Cancellation request recorded.');}catch(error){formError(error.message,form);}},'Requesting cancellation…');}
 }catch(error){formError(error.message,form);}
});
document.addEventListener('input',event=>{const name=event.target.name;if(name){event.target.removeAttribute('aria-invalid');const el=event.target.closest('form')?.querySelector(`[data-error-for="${name}"]`);if(el)el.textContent='';}if(event.target.closest('#draft-form'))captureDraft();});
document.addEventListener('change',async event=>{
 if(event.target.id==='overview-period'){const form=event.target.form;for(const name of ['from','to'])form.elements[name].disabled=event.target.value!=='custom';return;}
 if(event.target.id==='resolution-action'){resolutionSelection();return;}
 if(event.target.id==='processing-outcome'){outcomeSelection();return;}
 if(event.target.id==='operation-filter'){operationFilter=event.target.value;operationLimit=8;renderOperationChoices();return;}
 if(event.target.id==='operation-order'){if(event.target.value){operationOrderId=Number(event.target.value);route();}return;}
 const target=event.target;
 if(target.closest('#draft-form'))captureDraft();
 if(target.id==='review-payment-method'){
  const method=target.value,inModal=modal.open;
  const accepted=document.querySelector('#accept-prices');if(accepted)accepted.checked=false;
  document.querySelector('[data-action="submit-order"]').disabled=true;
  await processing('review-payment',null,async()=>{try{
    quote=null;
    if(inModal){const latest=await api('/orders/'+order.order_id);await api('/orders/'+order.order_id,'PUT',{...latest,payment_method:method});order=await api('/orders/'+order.order_id);}
    else{draft.payment_method=method;await persistDraft();order=await api('/orders/'+draft.order_id);draft.version=order.version;}
    quote=await api('/orders/'+order.order_id+'/review','POST',{});
    if(inModal)openReviewAgain();else draftView('#review-payment-method');
  }catch(error){formError(error.message,inModal?modal:document);}});
  return;
 }
 if(target.id==='payment-method'){captureDraft();quote=null;draftView('#payment-method');return;}
 if(target.id==='seller-select'){captureDraft();const next=Number(target.value);if(draft.items.length&&next!==Number(draft.seller_id)&&!confirm('Changing seller clears your selected items. Continue?')){target.value=draft.seller_id;return;}draft.seller_id=next;draft.items=[];quote=null;draftView('#seller-select');}
 if(target.dataset.quantity){const n=Number(target.value),item=draft.items.find(i=>i.offer_id===Number(target.dataset.quantity));item.quantity=n;if(!Number.isSafeInteger(n)||n<1||n>100000){target.setAttribute('aria-invalid','true');let error=target.parentElement.querySelector('.quantity-error');if(!error){error=document.createElement('span');error.className='field-error quantity-error';target.parentElement.append(error);}error.textContent='Use a whole number, 1–100,000.';return;}draftView(`[data-quantity="${item.offer_id}"]`);}
 if(target.id==='accept-prices')document.querySelector('[data-action="submit-order"]').disabled=!target.checked||!quote||busy.has('review-payment');
});
document.addEventListener('click',async event=>{
 const anchor=event.target.closest('a[href^="#"]');if(anchor&&!anchor.classList.contains('skip-link')&&me){event.preventDefault();leave(()=>{if(anchor.hash==='#operations'&&renderedHash.startsWith('#order/')&&order)operationOrderId=order.order_id;if(location.hash===anchor.hash)route();else location.hash=anchor.hash;});return;}
 if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main-content')?.focus();return;}const button=event.target.closest('[data-action]');if(!button)return;const name=button.dataset.action;if((busy.has('draft-mutation')||busy.has('submit')||busy.has('review-payment'))&&['stage','stage-next','add-item','remove-item','save-draft','edit-draft'].includes(name))return;
 try{
  if(name==='register'){registration();return;}
  if(name==='sign-in'){login();return;}
  if(name==='keep-editing'){pendingLeave=null;modal.close();return;}
  if(name==='discard-draft'){const work=pendingLeave;pendingLeave=null;draftActive=false;modal.close();return work?.();}
  if(name==='save-and-leave'){return await processing('draft-mutation',button,async()=>{await persistDraft();const work=pendingLeave;pendingLeave=null;draftActive=false;modal.close();toast('Draft saved.');await work?.();},'Saving…');}
  if(name==='use-saved'||name==='someone-else'){captureDraft();Object.assign(draft,name==='use-saved'?savedRecipient():{recipient_name:'',recipient_contact:'',requested_delivery_address:''});quote=null;draftView('[name="recipient_name"]');return;}
  if(name==='save-defaults'){captureDraft();return await processing('profile',button,async()=>{profile=await api('/profile','PUT',{...profile,contact_number:draft.recipient_contact,default_recipient_name:draft.recipient_name,default_delivery_address:draft.requested_delivery_address});toast('Default details saved.');draftView();},'Saving…');}
  if(name==='toggle-password'){const input=document.querySelector('#password-input'),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'Hide password':'Show password');button.querySelector('span').textContent=show?'Hide':'Show';return;}
  if(name==='demo-login')return await processing('login',button,async()=>{try{await signIn(button.dataset.email,'CampusDemo2026!');}catch(error){formError(error.message,document.querySelector('#login-form'));}},'Signing in…');
  if(name==='read-notification')return await processing('notification',button,async()=>{await api('/notifications/'+button.dataset.id+'/read','POST',{});await route();},'Saving…');
  if(name==='logout')return await leave(()=>processing('logout',button,async()=>{await api('/logout','POST',{});me=null;csrf='';draft=null;quote=null;epoch++;modal.close();login();},'Signing out…'));
  if(name==='operation-more'){operationLimit+=8;renderOperationChoices();return;}
  if(name==='operation-pick'){operationOrderId=Number(button.dataset.id);await route();document.querySelector('#processing-selected')?.scrollIntoView({block:'start'});return;}
  if(name==='order-again')return await processing('order-again',button,async()=>{const result=await api('/orders/'+order.order_id+'/order-again','POST',{});location.hash='edit/'+result.order_id;toast(result.removed_items?'New draft created. Unavailable products were omitted.':'New draft created using current prices. Review before submitting.');},'Creating draft…');
  if(name==='begin-issue-closure'||name==='issue-requirement-action'){const select=document.querySelector('#resolution-action');if(select){select.value=name==='begin-issue-closure'?'mark_resolved':button.dataset.resolutionAction;resolutionSelection();document.querySelector('#resolution-form')?.scrollIntoView({block:'start'});document.querySelector('#resolution-form textarea[name="reason"]')?.focus();}return;}
  if(name==='overview-reset'){overviewFilters={period:'month'};sessionStorage.removeItem('overviewFilters');await route();return;}
  if(name==='check-clearance')return await processing('clearance',button,async()=>{const result=await api('/orders/'+order.order_id+'/resolve','POST',{});await route();toast(result.pending?'Clearance is still awaiting the responsible service.':'Clearance checks updated.');},'Checking…');
  if(name==='resolve-stopped')return await processing('dispatch',button,async()=>{const result=await api('/orders/'+operationOrderId+'/resolve','POST',{});await route();toast(result.pending?'Resolution is still awaiting verification.':'Resolution checks updated. Order processing remains ended.');},'Checking resolution…');
  if(name==='refresh')return await leave(()=>processing('refresh',button,route,'Refreshing…'));
  if(name==='close-modal'){pendingLeave=null;modal.close();return;}
  if(name==='status-filter'){const p=filters();if(button.dataset.status)p.set('status',button.dataset.status);else p.delete('status');sessionStorage.setItem('orderFilters',p.toString());page=1;return await route();}
  if(name==='reset-filters'){sessionStorage.removeItem('orderFilters');page=1;return await route();}
  if(name==='page-prev'||name==='page-next'){page+=name==='page-prev'?-1:1;return await route();}
  if(name==='stage'){captureDraft();const next=Number(button.dataset.stage);if(next<=stage){stage=next;quote=null;draftView();headingFocus();}return;}
  if(name==='stage-next')return await processing('draft-mutation',button,advanceStage,stage===1?'Continuing…':'Saving & checking prices…');
  if(name==='add-item'){const id=Number(button.dataset.id),existing=draft.items.find(i=>i.offer_id===id);if(existing){if(existing.quantity>=100000)return toast('The maximum quantity is 100,000 per offer.');existing.quantity++;}else draft.items.push({offer_id:id,quantity:1});draftView(`[data-action="add-item"][data-id="${id}"]`);toast('Item added to your order.');return;}
  if(name==='remove-item'){draft.items=draft.items.filter(i=>i.offer_id!==Number(button.dataset.id));draftView('[data-action="stage-next"]');return;}
  if(name==='save-draft')return await processing('draft-mutation',button,async()=>{if(draft.items.some(i=>!Number.isSafeInteger(i.quantity)||i.quantity<1||i.quantity>100000))return formError('Fix the item quantities before saving.');await persistDraft();draftActive=false;quote=null;page=1;sessionStorage.setItem('orderFilters',new URLSearchParams({status:'draft'}).toString());location.hash='orders';await route();toast('Draft saved');},'Saving draft…');
  if(name==='new-customer'){customerDialog();return;}
  if(name==='review')return await processing('review',button,review,'Checking current prices…');
  if(name==='edit-draft'){modal.close();location.hash=`edit/${order.order_id}`;return;}
  if(name==='submit-order')return await processing('submit',button,submitOrder,'Submitting…');
  if(name==='cancel'){cancellationDialog();return;}
  if(name==='dispatch')return await processing('dispatch',button,async()=>{const ref=button.dataset.ref,select=[...document.querySelectorAll('[data-outcome]')].find(e=>e.dataset.outcome===ref);const result=await api('/operations/dispatch','POST',{request_reference:ref,outcome:button.dataset.scenario||select?.value||'success'});await route();toast(result.pending?'Result unresolved. Check for an update later.':'Service update received.');},'Checking result…');
 }catch(error){formError(name==='save-draft'&&(!error.status||error.status>=500)?'We couldn’t save your draft. Your entries are still here. Try Save draft again.':error.message,modal.open?modal:document);}
});
window.addEventListener('hashchange',()=>{if(draftActive&&(busy.has('draft-mutation')||busy.has('submit'))){history.replaceState(null,'',renderedHash||'#orders');return;}if(location.hash==='#main-content'){document.querySelector('#main-content')?.focus();return;}if(dirty()){const target=location.hash;history.replaceState(null,'',renderedHash||'#orders');leave(()=>{location.hash=target;});}else route();});
window.addEventListener('beforeunload',event=>{if(dirty()||busy.has('draft-mutation')||busy.has('submit')){event.preventDefault();event.returnValue='';}});
try{config=await api('/config');try{const result=await api('/me');me=result.user;csrf=result.csrf;}catch(error){if(error.status!==401)throw error;}await route();}catch(error){app.innerHTML=`<main class="connection-error"><span class="empty-icon">${icon('alert')}</span><h1>We couldn’t connect</h1><p>${esc(error.message)}</p><button type="button" id="reconnect">Try again</button></main>`;document.querySelector('#reconnect').addEventListener('click',()=>location.reload());}



}
start().catch(error=>{
 console.error('BSIT-44 Sales-Order Management startup failed:',error);
 const panel=document.createElement('main');panel.className='connection-error';panel.setAttribute('role','alert');
 const title=document.createElement('h1');title.textContent='We couldn’t load BSIT-44 Sales-Order Management';
 const message=document.createElement('p');message.textContent='If you just updated the project, restart the local server with npm.cmd run demo, then try again.';
 const retry=document.createElement('button');retry.type='button';retry.id='startup-retry';retry.className='primary';retry.textContent='Try again';retry.addEventListener('click',()=>location.reload());
 panel.append(title,message,retry);document.querySelector('#app').replaceChildren(panel);
});

setInterval(()=>{if(me?.role==='staff'&&location.hash==='#overview'&&!document.hidden&&!busy.size&&!document.activeElement?.closest('#overview-filter-form'))route();},60000);
